(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_01_01_08_WORBS_READER_DERIVATIVE_v0.1_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/1SA_01_01_08_WORBS_READER_DERIVATIVE_v0.1_20261017.md","sourceSha256":"439fbba733865477f11397723074a540f642f9b54b811324460dbb5e816f5eb5","passage":{"book":"1sa","chapter":1,"v1":1,"v2":8,"ref":"사무엘상 1:1–8"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"예배의 길 위에 놓인 한나의 눈물","overview":["사무엘상은 왕의 즉위나 전쟁의 승리로 시작하지 않습니다. 에브라임 산지의 한 가정, 해마다 실로 성소로 올라가는 가족, 그리고 자녀가 없어 고통받는 한나의 이야기로 문을 엽니다. 엘가나는 한나를 사랑하지만, 또 다른 아내 브닌나의 지속적인 괴롭힘과 자녀가 없는 현실을 해결하지 못합니다. 예배를 드리는 날조차 한나는 울며 먹지 못합니다."],"centralMessage":"사무엘상 1:1–8은 이스라엘의 새 시대가 시작될 무대를, 해결되지 않은 한 여성의 고통과 반복되는 예배의 자리에서 마련합니다. 하나님의 주권을 고백하는 서술은 한나의 상처를 죄의 결과로 판정하지 않으며, 인간의 위로가 미치지 못하는 자리를 드러낸 뒤 한나가 하나님께 직접 말하게 될 다음 장면을 준비합니다.","literaryStructure":[{"v1":1,"v2":2,"title":"왕궁이 아니라 한 가정에서 시작되는 이야기"},{"v1":3,"v2":3,"title":"실로로 올라가는 예배와 아직 드러나지 않은 균열"},{"v1":4,"v2":5,"title":"제물의 몫으로도 메워지지 않는 결핍"},{"v1":6,"v2":7,"title":"예배 때마다 반복되는 상처"},{"v1":8,"v2":8,"title":"사랑하지만 다 알지 못하는 남편의 질문"}],"sections":[{"id":"1sa1-1-2","v1":1,"v2":2,"title":"왕궁이 아니라 한 가정에서 시작되는 이야기","paragraphs":["첫 문장은 에브라임 산지의 라마다임소빔에 사는 엘가나를 소개하고, 그의 조상들을 거슬러 올라갑니다. 이처럼 인물의 거주지와 가계를 제시하는 방식은 앞으로 일어날 일을 한 가정의 구체적인 역사 속에 놓습니다. 그러나 화자가 독자에게 먼저 알려 주는 결정적인 사실은 엘가나의 지위나 재산이 아닙니다. 그에게 한나와 브닌나라는 두 아내가 있으며, 브닌나에게는 자녀가 있고 한나에게는 없다는 사실입니다. 이 대비가 뒤따르는 모든 장면의 정서적 출발점이 됩니다.","두 아내가 있다는 사실은 고대 사회의 가정 구조를 보여 주지만, 서술이 그 관계를 이상적인 모습으로 칭찬하는 것은 아닙니다. 오히려 두 사람의 처지가 비교되면서 한 가정 안의 상처와 경쟁이 전면에 나타납니다. 창세기에서 사라와 하갈, 레아와 라헬 사이에 나타났던 긴장을 떠올리게 하지만, 인물들의 사정과 행동이 모두 같다고 볼 수는 없습니다. 이 연결이 중요한 이유는 성경이 출산과 계승의 문제를 다룰 때 인간의 통제 밖에 있는 한계와 그 안에서 벌어지는 관계의 갈등을 함께 보여 준다는 데 있습니다.","엘가나의 출신지인 라마다임소빔은 본문의 지리적 출발점입니다. ‘에브라임 사람’이라는 표현은 이 지역과의 연관을 나타내지만, 그것만으로 그의 혈통 전체를 확정할 수는 없습니다. 또한 고대 지명을 현대의 특정 지점과 일대일로 대응시키는 데에는 별도의 증거가 필요합니다. 본문이 우선 알려 주는 것은 이 가족이 에브라임 산지에서 살았다는 사실입니다."]},{"id":"1sa1-3-3","v1":3,"v2":3,"title":"실로로 올라가는 예배와 아직 드러나지 않은 균열","paragraphs":["엘가나는 해마다 자기 성읍에서 실로로 올라가 ‘만군의 여호와’께 경배하고 제사를 드립니다. 가족의 삶에는 정기적인 예배의 리듬이 있습니다. 여기서 ‘올라간다’는 말은 성소를 향한 이동을 서술하며, 본문은 그 순례가 반복되었다는 사실을 강조합니다. 출발지와 목적지는 제시되지만 이동 경로, 걸린 시간, 중간 기착지는 기록되지 않습니다. 따라서 이 구절을 세밀한 고대 도로 지도로 바꾸기보다, 가족이 일상에서 성소로 나아가는 반복적인 움직임으로 이해하는 것이 적절합니다.","‘만군의 여호와’(יְהוָה צְבָאוֹת, 여호와 체바오트)는 여호와의 통치와 권능을 드러내는 호칭입니다. 여기서 ‘만군’을 곧바로 이스라엘의 군대 하나로만 좁힐 필요는 없습니다. 이 호칭은 앞으로 왕과 전쟁, 나라의 운명을 다룰 사무엘상 전체를 내다보게 합니다. 그러나 첫 장면에서 그 하나님께 나아가는 사람은 군대를 이끄는 왕이 아니라 자녀가 없어 슬퍼하는 한 여성의 가족입니다. 큰 역사를 다스리시는 하나님과 한 사람의 고통이 같은 서사의 첫머리에 놓인 것입니다.","화자는 실로에 엘리의 두 아들 홉니와 비느하스가 제사장으로 있었다는 사실도 미리 말합니다. 3절만으로 그들의 죄를 모두 알 수는 없지만, 뒤따르는 2장에서는 그들이 제사를 멸시하고 성소를 더럽히는 행위가 드러납니다. 그러므로 이 짧은 소개는 성소 자체가 아무 문제 없는 공간이라는 기대를 서서히 흔듭니다. 한나의 가정에서 일어나는 상처와 제사장 집안의 위기는 아직 다른 장면이지만, 이야기의 진행 속에서 서로를 비추게 됩니다."]},{"id":"1sa1-4-5","v1":4,"v2":5,"title":"제물의 몫으로도 메워지지 않는 결핍","paragraphs":["제사를 드리는 날 엘가나는 브닌나와 그 자녀들에게 제물의 몫을 나누어 주고 한나에게도 몫을 줍니다. 이 식사 장면은 가족이 함께 제사에 참여하고 있음을 보여 주면서 동시에 자녀가 있는 사람과 없는 사람의 차이를 다시 드러냅니다. 한나를 사랑한다는 엘가나의 마음은 분명하지만, 그 사랑이 곧 한나의 고통을 없애 주지는 못합니다.","5절의 히브리어 표현 מָנָה אַחַת אַפָּיִם(마나 아하트 압파임)은 번역이 쉽지 않습니다. 흔히 한나에게 ‘갑절의 몫’을 주었다고 옮기지만, ‘특별한 몫’이나 ‘한 몫’으로 이해하는 견해도 있습니다. 따라서 제물의 정확한 양을 확정해 이야기의 의미를 세우는 것은 조심해야 합니다. 본문에서 분명한 것은 엘가나가 한나를 사랑했다는 사실과, 그 사랑에도 불구하고 한나의 태가 닫혀 있었다는 사실입니다.","서술자는 ‘여호와께서 그의 태를 닫으셨다’고 말합니다. 이 표현은 생명이 인간의 뜻대로 주어지는 것이 아니라는 신앙적 인식을 드러냅니다. 그러나 한나가 어떤 잘못을 저질렀기 때문에 자녀를 갖지 못했다는 설명은 본문 어디에도 없습니다. 하나님의 주권을 고백하는 서술을 고통받는 사람에 대한 도덕적 판결로 바꾸면, 본문이 말하지 않는 원인을 만들어 내게 됩니다."]},{"id":"1sa1-6-7","v1":6,"v2":7,"title":"예배 때마다 반복되는 상처","paragraphs":["브닌나는 한나를 심히 격동시키고 괴롭힙니다. 히브리어 צָרָה(차라)는 문맥에 따라 경쟁 상대나 적대적인 처지의 사람을 가리킬 수 있습니다. 여기서는 같은 남편을 둔 다른 아내가 한나에게 적대적으로 행동하는 관계를 드러냅니다. 이어지는 자극과 괴롭힘의 표현은 한나가 단순히 남과 비교하며 속상해한 정도가 아니라, 타인의 의도적인 공격을 겪고 있음을 보여 줍니다.","7절은 이 일이 ‘매년’ 되풀이되었다고 말합니다. 한나의 눈물은 하루의 돌발적인 감정이 아닙니다. 실로에 올라가는 정기적인 예배의 때마다 괴롭힘이 다시 시작되었고, 그 결과 한나는 울며 먹지 못했습니다. 제사의 식사가 가족의 기쁨과 교제를 나타낼 수 있는 자리에서, 한나는 그 식사에 참여할 힘마저 잃습니다. 성소를 찾는 신앙생활과 깊은 슬픔이 같은 시간에 존재한다는 사실이 이 장면의 긴장입니다.","이 대목은 브닌나의 공격을 정당화하지도, 한나의 눈물을 믿음이 부족하다는 표시로 설명하지도 않습니다. 서술자는 오히려 상처의 반복을 충분히 보여 줌으로써 다음 장면에서 한나가 왜 자신의 마음을 여호와 앞에 쏟아 놓는지 이해하게 합니다. 한나의 기도는 아무 문제 없는 사람이 신앙적 열심을 보이기 위해 덧붙인 행동이 아니라, 오래 지속된 고통 속에서 나오는 말입니다."]},{"id":"1sa1-8-8","v1":8,"v2":8,"title":"사랑하지만 다 알지 못하는 남편의 질문","paragraphs":["엘가나는 한나에게 왜 울며 먹지 않고 마음이 슬프냐고 묻습니다. 그는 아내의 눈물과 식욕 상실을 알아차립니다. 이어 ‘내가 그대에게 열 아들보다 낫지 아니하냐’고 말하며 자신의 사랑으로 한나를 위로하려 합니다. ‘열 아들’은 많은 아들을 가리키는 강조 표현으로 읽을 수 있으며, 실제 자녀 수를 세는 정보로 취급할 필요는 없습니다.","그의 말에는 애정이 담겨 있지만, 한나가 겪는 고통을 충분히 이해하지 못하는 한계도 드러납니다. 남편의 사랑은 소중하지만 브닌나의 공격과 자녀가 없다는 현실을 대신 해결해 주지는 못합니다. 본문은 엘가나를 악인으로 단정하지 않습니다. 동시에 그가 좋은 뜻으로 건넨 말이 한나의 눈물을 멈추게 했다고도 기록하지 않습니다.","이렇게 첫 여덟 절은 해결책을 내놓지 않은 채 멈춥니다. 독자는 한나의 처지를 알게 되었지만, 아직 한나 자신의 긴 기도를 듣지 못했습니다. 9절 이후 한나는 일어나 여호와 앞에 나아가며, 자신의 쓰라린 마음을 직접 말합니다. 첫 단락의 문학적 역할은 한나의 고통을 서둘러 설명하거나 없애는 데 있지 않습니다. 그 고통을 있는 그대로 드러내고, 이제 하나님 앞에서 시작될 새로운 대화를 준비하는 데 있습니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘만군의 여호와’라는 호칭의 기능","paragraphs":["צְבָאוֹת(체바오트)는 ‘군대들’, ‘무리들’과 관련된 말입니다. 그 지시 범위를 하나의 군사 조직으로 한정하기보다는 여호와의 광범한 통치권을 드러내는 칭호로 읽는 것이 자연스럽습니다. 왕정으로 향하는 책의 도입부에 이 이름이 놓였다는 점은 의미가 있지만, 이 한 구절만으로 후대의 왕권 신학 전체가 이미 상세히 전개되었다고 말할 수는 없습니다."]},{"title":"5절의 제물 분배와 번역의 한계","paragraphs":["מָנָה אַחַת אַפָּיִם의 정확한 뜻에는 논의가 남아 있습니다. ‘갑절’이라는 익숙한 번역을 유일한 정답으로 삼거나, 반대로 엘가나가 한나를 홀대했다고 결론 내리기 어렵습니다. 서술이 직접 밝히는 사랑과 한나의 지속되는 슬픔을 함께 읽어야 합니다."]},{"title":"하나님의 주권과 인간의 가해를 구별하기","paragraphs":["5–6절의 ‘여호와께서 태를 닫으셨다’는 서술과 브닌나가 한나를 괴롭혔다는 서술은 서로 다른 행위를 말합니다. 본문은 한나의 불임을 하나님 주권 아래에 놓지만, 그 사실을 브닌나의 모욕에 대한 정당화로 사용하지 않습니다. 또한 고난의 원인을 한나 개인의 죄에서 찾지 않습니다. 이 구분은 본문 자체의 인물 평가를 보존하는 데 중요합니다."]},{"title":"앞뒤 본문과의 관계","paragraphs":["창세기 29–30장의 레아와 라헬 이야기는 출산과 가족 내 경쟁이 서로 얽힐 때 생기는 긴장을 보여 줍니다. 사무엘상 1:9–20은 한나가 이 고통을 여호와 앞에 말하고, 1:21–28은 받은 아들을 봉헌하는 과정을 전합니다. 사무엘상 2:1–10의 한나의 노래는 개인의 경험을 낮은 자를 높이시고 교만한 자를 낮추시는 하나님의 통치로 확장합니다. 이 뒤의 내용을 첫 여덟 절에 미리 모두 집어넣기보다, 첫 장면이 제기한 질문이 어떻게 전개되는지를 따라 읽는 편이 좋습니다."]}],"relatedResearch":[],"readerSources":[],"notes":["성경 본문: 대한성서공회, 『성경전서 개역한글판』, 사무엘상 1:1–8; 창세기 16장, 29–30장; 사무엘상 1:9–2:10. 히브리어 표현은 사무엘상 1:1–8의 마소라 본문을 기준으로 검토하였습니다."],"sourceNotice":""},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_01_21_28_WORBS_STORY_COMMENTARY_v0.1_READER_DRAFT_20261019","researchType":"WORBS","researchDepth":"CORE","sourcePath":"C:/Users/언약의~1/AppData/Local/Temp/claude/C--Users--------codex-worktrees-judebible-runtime-integration---/420bbf84-ea58-448d-a604-848c12f3f224/scratchpad/conv/1SA_01_21_28_WORBS_STORY_COMMENTARY_v0.1_READER_DRAFT_20261019.md","sourceSha256":"89a4ea6a2d44b460d33e25321d27bca7c3610171a2e95a15675583244deaffb3","passage":{"book":"1sa","chapter":1,"v1":21,"v2":28,"ref":"사무엘상 1:21–28"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"받은 아들을 다시 여호와 앞에 세우다","overview":["한나가 여호와께 구하여 얻은 아들 사무엘은 이제 가족의 일상 속에서 자랍니다. 엘가나가 가족을 이끌고 해마다 실로로 올라갈 때 한나는 곧장 동행하지 않습니다. 아이가 젖을 뗄 때까지 돌본 뒤 그를 여호와 앞에 데려가 평생 그곳에 머물게 하겠다고 말합니다. 엘가나는 그 결정을 받아들이고, 때가 이르자 한나는 제물을 가지고 아이와 함께 실로에 올라갑니다. 이전에 한나의 기도를 오해했던 엘리 앞에서 그는 자신이 바로 그때 기도하던 여자라고 밝힙니다. 그리고 여호와께서 청원을 들어주셨으므로 이제 아들을 여호와께 드린다고 고백합니다."],"centralMessage":"이 단락의 중심은 기도 응답을 받은 뒤의 기쁨을 반복하는 데 있지 않습니다. **하나님이 주신 생명과 한나가 지킨 약속이 다시 여호와 앞에서 만나는 것**이 이야기의 결말입니다. 1:11에서 아직 태어나지 않은 아들을 평생 드리겠다고 한 서원은 1:28에서 실제 행위가 됩니다. 한나의 봉헌은 아이의 삶을 잠시 맡기는 거래가 아니라, 여호와께 받은 선물을 여호와께 속한 삶으로 인정하는 행동입니다. 이 개인적 사건은 곧 성소에서 자라 하나님의 말씀을 듣게 될 사무엘의 이야기를 열고, 한나의 노래(2:1–10)에서 하나님의 통치에 관한 더 큰 고백으로 이어집니다.","literaryStructure":[{"v1":21,"v2":22,"title":"가족은 다시 실로로 향하지만 한나는 남는다"},{"v1":23,"v2":23,"title":"엘가나의 동의와 약속을 지키는 시간"},{"v1":24,"v2":25,"title":"아이와 제물을 데리고 실로에 올라가다"},{"v1":26,"v2":27,"title":"‘그때 여기 서 있던 여자가 바로 저입니다’"},{"v1":28,"v2":28,"title":"‘구하여 받은 아이’를 평생 여호와께 드리다"}],"sections":[{"id":"1sa1-21-22","v1":21,"v2":22,"title":"가족은 다시 실로로 향하지만 한나는 남는다","paragraphs":["사무엘이 태어난 뒤에도 엘가나의 집안에서 해마다 드리던 예배는 계속됩니다. 21절은 엘가나가 온 집안을 데리고 올라가 여호와께 연례 제사와 자기의 서원을 드리려 했다고 말합니다. 첫 장면(1:3)의 순례가 반복되지만, 독자가 그 순례를 보는 눈은 달라졌습니다. 그때 실로는 한나가 모욕과 눈물 속에서 기도했던 장소였고, 이제는 그 기도로 얻은 아들을 데려가야 할 장소가 되었습니다. 같은 길이지만 서사 안에서 그 길이 지닌 의미는 변했습니다.","21절은 엘가나의 서원을 언급합니다. 본문은 그 서원의 구체적 내용을 설명하지 않습니다. 앞에서 분명히 소개된 서원은 한나의 것이므로(11절), 엘가나의 서원을 곧바로 한나의 서원과 완전히 동일하다고 단정할 수는 없습니다. 그러나 남편의 예배와 아내의 결단이 따로 흩어진 사건으로 묘사되는 것도 아닙니다. 이 가족은 여호와께 드리는 제사라는 공동의 삶 속에 있고, 바로 그 가운데 한나의 특별한 약속이 이행될 준비를 합니다.","한나는 이번에는 올라가지 않겠다고 말합니다. 이유는 서원을 잊었기 때문이 아니라 아이가 젖을 뗄 때까지 기다리려 하기 때문입니다. 그는 그때 아이를 데리고 가 여호와 앞에 보이게 하고 거기에 계속 머물게 하겠다고 밝힙니다. 히브리어에서 ‘젖을 떼다’는 말은 가말(גמל) 어근의 형태로 나타납니다. 이 단어는 아이가 젖먹이 시기를 지나가는 실제 양육의 단계를 가리킵니다. 본문은 그 기간을 몇 개월이나 몇 년이라고 계산해 주지 않습니다. 특정한 나이를 확정해 이 장면에 끼워 넣는 것보다, 아이를 돌보는 시간과 봉헌의 때를 구별하는 서술에 주목하는 것이 정확합니다.","한나가 기다린다는 사실은 그의 약속을 약하게 만들지 않습니다. 서원은 즉각적인 이동만으로 완성되는 것이 아니라, 아이를 기르고 때가 이르기를 기다리는 과정 속에서도 지속됩니다. 앞 단락의 한나가 기도하며 하나님의 기억하심을 기다렸다면, 여기서는 이미 받은 아이를 돌보며 자신의 약속을 이행할 때를 기다립니다. 이야기의 시간은 단숨에 뛰어넘지 않습니다. 한나의 기도와 봉헌 사이에는 아이가 자라는 일상의 시간이 놓여 있습니다.","‘여호와 앞에 보인다’는 표현은 실로 성소에서 하나님 앞에 나아가는 예배의 언어입니다. 그것을 오늘날의 건물 평면이나 정해진 예식 순서로 상세히 복원할 수는 없습니다. 본문이 밝히는 것은 한나가 아이를 여호와께 드리겠다고 한 약속을 성소에서 실제로 이루려 한다는 점입니다. 또 ‘계속 머문다’는 말은 잠시 들렀다가 돌아오는 연례 방문과 구별됩니다. 가족의 반복되는 순례와 사무엘의 지속적인 성소 생활이 여기서 갈라지기 시작합니다."]},{"id":"1sa1-23-23","v1":23,"v2":23,"title":"엘가나의 동의와 약속을 지키는 시간","paragraphs":["엘가나는 한나에게 그가 보기에 좋은 대로 하라고 말하며 아이가 젖을 뗄 때까지 머물도록 합니다. 이 대화는 앞의 가족 갈등과 대조됩니다. 한나가 먹지 못하고 울던 때 엘가나는 위로하려 했지만 그 말만으로 한나의 고통을 해결하지 못했다(1:8). 이번에는 한나가 말한 계획을 듣고 그 실행을 받아들입니다. 본문이 그의 모든 내면을 설명하는 것은 아니지만, 적어도 이 장면에서 그는 한나의 결정을 가로막지 않습니다.","그가 덧붙인 ‘여호와께서 그의 말씀을 이루시기를’이라는 말은 해석할 여지가 있습니다. 히브리어 마소라 본문에는 ‘그의 말씀’(דְּבָרוֹ)이라는 형태가 있습니다. 이를 여호와의 말씀으로 읽으면, 하나님께서 앞서 이루어 주신 일과 앞으로 아이에게 행하실 일을 신뢰하는 간구가 됩니다. 그러나 바로 앞에 한나의 서원이 놓여 있으므로, 고대 전승과 번역에서는 한나의 말이 이루어지기를 바라는 뜻으로 이해하기도 합니다. 이 차이는 누가 서원을 했는가 하는 질문과 연결되지만, 어느 쪽을 택하든 본문의 분명한 사건은 같습니다. 엘가나는 한나의 기다림을 허락하고, 한나는 아이가 젖을 뗄 때까지 집에 머물러 그를 기릅니다.","서원을 둘러싼 고대 이스라엘의 가정법을 생각할 때 민수기 30장은 관련 본문입니다. 그 장은 가정 안에서 이루어진 서원과 남편의 반응을 다룹니다. 그렇지만 사무엘상 1장은 그 법의 절차를 하나하나 재현하려는 법률 사례가 아닙니다. 엘가나의 말을 특정 법 조항의 형식적 승인으로만 축소하면, 서술이 강조하는 한나의 주도적인 발화와 양육의 시간을 놓치기 쉽습니다. 이 대목은 두 사람이 주고받은 실제 말과 그 뒤에 이어진 행동을 중심으로 읽어야 합니다.","23절은 한나가 머물며 아들에게 젖을 먹였다고 끝맺습니다. 한나가 ‘드린다’고 말한 아이를 당장 떠나보내지 않고 먼저 먹이고 기른다는 사실은 중요합니다. 서원 이행이 어머니의 양육과 서로 적대하는 일처럼 그려지지 않기 때문입니다. 본문은 이 시간이 한나에게 어떤 감정이었는지 말하지 않으므로 그 마음을 상상해 채울 필요는 없습니다. 다만 서술은 약속의 이행이 돌봄의 과정을 지나 완성된다는 점을 조용하고 분명하게 보여 줍니다."]},{"id":"1sa1-24-25","v1":24,"v2":25,"title":"아이와 제물을 데리고 실로에 올라가다","paragraphs":["아이가 젖을 떼자 한나는 그를 데리고 실로에 있는 여호와의 집으로 올라갑니다. 이 이동은 22절에서 한 말의 실행입니다. 이야기의 초반에는 한나가 성소에서 아들을 구했고, 이제는 아들과 함께 성소에 돌아옵니다. 화자는 이 두 장면을 서로 비추어 놓습니다. 한나가 얻은 것은 집 안에서만 기념되는 사적인 성취로 남지 않고, 처음 기도했던 자리에서 다시 여호와께 관계 지어집니다.","24절은 제물도 함께 기록합니다. 마소라 히브리어 본문은 수소 세 마리, 밀가루 한 에바, 포도주 한 부대를 언급합니다. 이 물품은 예배가 말뿐인 결심이 아니라 실제 제사 행위와 함께 이루어진다는 사실을 보여 줍니다. 그러나 제물의 양을 오늘날의 정확한 무게나 부피로 환산하거나, 각 제물이 반드시 어떤 세부 제사 종류였다고 단정할 필요는 없습니다. 특히 25절은 ‘그 수소’를 잡았다고 단수로 말하므로, 24절의 수량과 25절의 표현을 함께 읽어야 합니다.","이 지점에는 중요한 본문 전승의 차이도 있습니다. 마소라 본문은 ‘수소 세 마리’라고 읽지만, 고대 그리스어 번역과 쿰란의 사무엘서 전승은 ‘세 살 된 수소 한 마리’라는 읽기를 뒷받침합니다. 어느 표현이 더 이른 본문을 보존하는가를 두고 본문비평적 논의가 있습니다. 따라서 독자에게 제물의 숫자 자체를 확정적인 신학적 상징으로 설명하는 것은 신중해야 합니다. 분명한 것은 한나가 아이를 데리고 제사에 필요한 것을 갖추어 실로에 왔으며, 그 자리에서 사무엘을 엘리에게 데려왔다는 사건의 흐름입니다.","서술자는 ‘아이는 아직 어렸다’고 덧붙입니다. 히브리어 표현은 나아르(נַעַר, 아이·소년)를 반복해 그가 아직 어린 상태임을 강조합니다. 그가 몇 살이었는지 숫자를 알려 주는 문장은 아닙니다. 이 짧은 말은 한나의 서원이 지닌 무게를 드러냅니다. 훗날 이미 성장한 지도자를 보내는 것이 아니라, 아직 어린 아이를 여호와께 드리는 장면이기 때문입니다. 그렇다고 본문에 없는 아이의 두려움이나 부모의 작별 대화를 만들어 낼 수는 없습니다. 화자는 아이의 나이와 감정보다 그가 여호와 앞에 놓이게 되는 사건을 앞세웁니다.","25절은 제사를 드린 뒤 아이를 엘리에게 데려왔다고 말합니다. 이전에 엘리는 한나의 입술을 보고 그를 술 취한 사람으로 오해했다(1:12–14). 이번에는 한나가 그 앞에 아들을 데리고 섭니다. 두 만남 사이에 여호와의 기억하심과 아이의 출생이 놓여 있습니다. 엘리는 이제 한나가 누구인지, 그때 무슨 기도를 했는지 그녀 자신의 설명을 듣게 됩니다. 이 반복되는 만남은 하나님의 응답을 제사장의 능력으로 돌리지 않으면서도, 성소와 제사장의 역할을 이야기에서 지워 버리지 않습니다."]},{"id":"1sa1-26-27","v1":26,"v2":27,"title":"‘그때 여기 서 있던 여자가 바로 저입니다’","paragraphs":["한나는 엘리에게 자신의 말을 들어 달라는 정중하고 단호한 호소로 시작합니다. 이어 자신이 바로 이곳에서 여호와께 기도하며 서 있던 여자라고 밝힙니다. 1:9–18을 기억하는 독자에게 이 말은 설명 이상의 힘을 가집니다. 엘리는 그때 한나의 입술을 보았지만 기도의 내용을 알지 못했고, 한나는 자신이 술 취한 사람이 아니라 여호와 앞에 마음을 쏟는 사람이라고 설명해야 했습니다. 이제 그 여자가 자신이 기도하던 바로 그 아이를 데리고 돌아왔습니다.","한나는 자신의 기도를 과장하거나 엘리가 기적을 만들어 냈다고 말하지 않습니다. 그는 이 아이를 위하여 기도했고, 여호와께서 자신이 구한 것을 주셨다고 증언합니다. ‘구한 것’에 해당하는 쉐엘라(שְׁאֵלָה)와 ‘구하였다’에 해당하는 샤알(שאל) 어근은 앞에서 사무엘의 이름과 연결되었던 말을 다시 들려준다(1:17, 20). 아이는 한나가 청원한 대상이자, 여호와께서 응답으로 주신 존재입니다. 같은 어근이 이어지는 28절의 봉헌 표현에까지 반복되면서, 기도와 응답과 드림을 하나의 문학적 흐름으로 묶습니다.","이 고백에서 주목할 점은 한나가 받은 선물의 근원을 분명히 말한다는 것입니다. 아이를 낳은 현실적인 과정은 사라지지 않지만, 화자는 그 사건을 여호와의 기억하심과 응답으로 이해한다(1:19–20). 그렇다고 이 이야기를 모든 간구가 반드시 같은 방식으로 이루어진다는 보편 법칙으로 바꾸어서는 안 됩니다. 사무엘상은 한나와 사무엘에게 일어난 특정한 일을 기록하며, 그 출생을 이후 이스라엘의 말씀과 왕정 역사로 연결합니다.","26–27절의 발화는 앞 단락의 미해결 관계도 정리합니다. 한나의 기도를 오해했던 제사장은 이제 그 기도의 응답을 듣는 사람이 됩니다. 그때 엘리의 축복은 미래를 확정적으로 통제하는 말이 아니었고(1:17), 지금 한나가 말하는 응답의 주체도 엘리가 아닙니다. 서사의 중심에는 한나를 기억하신 여호와가 있습니다. 동시에 한나가 자신의 이야기를 스스로 말한다는 점도 중요합니다. 본문은 그를 단지 다른 인물들의 설명을 통해 알려지는 사람이 아니라, 하나님이 행하신 일을 직접 증언하는 인물로 세웁니다."]},{"id":"1sa1-28-28","v1":28,"v2":28,"title":"‘구하여 받은 아이’를 평생 여호와께 드리다","paragraphs":["28절에서 한나는 응답의 이야기를 자신의 결단으로 이어 갑니다. 그가 여호와께 구하여 얻은 아이를 이제 여호와께 드린다는 것입니다. 이 문장에는 샤알(שאל) 어근이 여러 형태로 겹쳐 나타납니다. 27절에서 ‘구하다’와 ‘청원’으로 쓰인 말이 28절에서는 ‘드리다·넘겨드리다’라는 뜻을 전하는 히필형 히쉬일티후(הִשְׁאִלְתִּהוּ)와 ‘여호와께 드려진 자’라는 표현으로 이어집니다. 번역에 따라 ‘빌려주다’라는 말이 나타나기도 하지만, 일상적인 대여처럼 일정 기간 뒤에 되찾는다는 뜻으로 읽으면 문맥을 놓치게 됩니다. 한나는 곧바로 ‘그의 평생’을 말합니다. 이 약속은 일시적인 방문이나 임시 봉사가 아닙니다.","11절에서 한나는 아직 태어나지 않은 아들을 평생 여호와께 드리겠다고 말했습니다. 28절은 그 약속을 되풀이하면서도, 이제는 실제로 아이를 엘리 앞에 데려왔다는 점에서 다릅니다. 서원의 말과 이행의 행동이 만나는 것입니다. 이야기는 한나가 아들을 얻었으므로 자신의 소원이 끝났다고 선언하지 않습니다. 오히려 그 소원은 아이의 삶이 여호와께 속한다는 인정으로 나아갑니다. 하나님이 주신 것을 다시 하나님께 드린다는 말은 하나님의 은혜를 얻기 위한 값을 지불한다는 뜻이 아닙니다. 이미 받은 은혜를 어떻게 이해하고 응답하는가를 보여 주는 서사적 결말입니다.","여기서 사무엘의 미래는 한나의 의도만으로 다 설명되지 않습니다. 한나는 그를 여호와께 드리지만, 뒤이어 사무엘이 어떻게 성장하고 하나님의 말씀을 듣게 되는지는 2–3장이 보여 줍니다. 또 실로 성소는 이후 엘리의 아들들이 제사를 멸시하는 장소로 묘사된다(2:12–17). 그러므로 이 봉헌을 성소의 모든 제도와 인물이 이미 온전하다는 승인으로 읽을 수 없습니다. 본문은 불완전한 인간의 제도 안에서도 여호와께서 사무엘의 삶을 이끄시는 이야기를 시작합니다.","28절 끝에는 그곳에서 여호와께 경배했다는 말이 나옵니다. 마소라 본문의 동사는 남성 단수형이지만, 그 주체가 사무엘인지 엘가나인지 본문만으로 확정하기 어렵습니다. 고대 역본과 번역들에는 복수로 옮기거나 표현을 달리하는 전승도 있습니다. 경배의 주체를 한 사람으로 확정하는 것보다 중요한 것은 이 단락이 여호와 앞에서의 경배로 닫힌다는 점입니다. 실로에 올라가는 것으로 시작한 이야기가 실로에서 아이를 드리고 예배하는 것으로 끝납니다.","그러나 사무엘의 이야기는 여기서 멈추지 않습니다. 2:1–10에서 한나는 다시 입을 열어 기도합니다. 이번에는 자신의 사정만이 아니라 높고 낮은 자의 운명을 바꾸시고 왕을 세우시는 여호와의 통치를 노래합니다. 사무엘의 봉헌은 한 가정의 이야기이면서, 하나님께서 이스라엘의 역사 속에 말씀의 종을 세우시는 더 큰 이야기의 문턱이 됩니다. 이 단락은 한나의 기도가 응답되었다는 사실과, 응답받은 생명이 여호와께 속한다는 고백을 함께 놓습니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"서원의 이행과 젖을 뗄 때까지의 기다림","paragraphs":["1:21의 ‘그의 서원’은 문법상 엘가나와 연결되지만, 그 구체적인 내용은 밝혀지지 않습니다. 1:11과 1:22–23은 한나 자신의 서원과 실행 계획을 분명히 보여 줍니다. 민수기 30장의 가정 내 서원 규정은 배경을 이해하는 데 도움이 되지만, 그 규정을 곧바로 사무엘상 1장의 모든 발화에 대응시키는 것은 본문이 제공하는 정보보다 나아갑니다. 또한 젖을 뗀 정확한 연령은 본문에 없습니다. 기다림의 기간은 아이의 양육과 약속의 이행 사이에 놓인 실제 시간으로 읽는 것이 적절합니다."]},{"title":"23절의 ‘그의 말씀’과 고대 전승","paragraphs":["마소라 본문은 ‘여호와께서 그의 말씀을 이루시기를’이라고 읽을 수 있는 표현을 보존합니다. 그런데 한나의 서원에 초점을 두는 전승에서는 ‘당신의 말’ 또는 한나의 약속이 이루어지는 의미가 두드러집니다. 이 차이는 여호와의 약속과 한나의 서원을 어떻게 연결할 것인지에 영향을 주지만, 한나가 아이를 기르고 엘가나가 이를 허락했다는 서사적 사실을 바꾸지는 않습니다. 본문비평에서는 어느 읽기가 먼저였는지를 단순한 번역 취향만으로 판정할 수 없습니다. 이 쟁점은 한나의 서원 전승을 연구한 Anneli Aejmelaeus의 논문 초록과 함께 검토하였습니다."]},{"title":"24–25절의 수소 수량 문제","paragraphs":["마소라 본문은 בְּפָרִים שְׁלֹשָׁה, 곧 ‘수소 세 마리’로 읽히지만, 고대 그리스어 역본과 4QSamᵃ의 읽기는 ‘세 살 된 수소 한 마리’를 지지합니다. 25절의 단수 ‘그 수소’도 논의에 영향을 줍니다. Ehud Ben Zvi, Maxine Hancock, Richard A. Beinert의 히브리어 독해 교재는 이 차이를 단순 필사 실수로만 처리하지 않고, 제사에 대한 해석과 본문 전승의 관계 속에서 살핍니다. 어느 쪽이 최초 형태인지에 대한 판단과 별개로, 원고의 기본 주석에서는 제물의 정확한 수량에 신학적 의미를 억지로 부여하지 않았습니다. 제물과 함께 아이를 여호와의 집에 데려왔다는 중심 사건은 두 전승에서 유지됩니다."]},{"title":"‘구하다’에서 ‘드리다’로 이어지는 원어의 힘","paragraphs":["27절의 שְׁאֵלָתִי(나의 청원), שָׁאַלְתִּי(내가 구하였다)와 28절의 הִשְׁאִלְתִּהוּ(내가 그를 드렸다), שָׁאוּל(구해진·드려진)은 같은 שאל 어근을 중심으로 연결됩니다. 이는 사무엘 이름의 확정된 역사언어학적 어원을 제시하는 증거라기보다, 사무엘의 출생과 봉헌을 묶는 문학적 말놀이입니다. 훗날 사울의 이름 역시 비슷한 소리를 지니지만, 이 대목이 사울 왕의 등장을 의도적으로 암호화했다고 단정할 수는 없습니다. 독자는 먼저 이 단락 안에서 ‘청원–응답–봉헌’의 논리가 어떻게 완성되는지를 읽어야 합니다."]},{"title":"끝의 경배와 이어지는 노래","paragraphs":["28절 마지막의 וַיִּשְׁתַּחוּ는 남성 단수형이므로, 현대 번역에서 ‘그가 경배했다’ 또는 ‘그들이 경배했다’로 처리하는 차이가 생깁니다. 행위자를 단정하기 어려워도 경배가 결말이라는 점은 분명합니다. 이어지는 2:1–10은 한나의 찬양을 통해 개인의 경험을 낮은 자를 높이시고 교만한 자를 낮추시는 하나님의 통치로 확장합니다. 이 연결은 사무엘상 전체에서 말씀과 왕권을 둘러싼 갈등을 읽는 중요한 출발점이지만, 1:21–28 자체에 아직 등장하지 않는 사건을 이미 일어난 일처럼 서술해서는 안 됩니다."]}],"relatedResearch":[],"readerSources":[],"notes":["연구 참고자료","* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:21–28 및 연결 본문 대조 · 저작권자: 대한성서공회. 공개 재배포 허락은 별도 확인이 필요합니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.1.21–28 히브리어 본문·표제어·형태 분석 · 형태·표제어 자료 CC BY 4.0; 기반 Westminster Leningrad Codex(WLC) 본문 Public Domain.\n   * 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n   * 원저작 표시: Open Scriptures Hebrew Bible Project, https://github.com/openscriptures/morphhb\n   * 히브리어 어형과 문맥상 의미를 한국어 설명으로 재서술하였습니다. 원어 본문의 판본 자체를 수정하지 않았습니다.\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · 「WORBS_사무엘상1장_필터최소패치_v0.2」, 사무엘상 1:1–28 · 기존 연구 원고의 서술·문학 구조·정경 연결을 참조하였습니다. 권리 조건은 별도 확인 대상입니다.\n* *Readings in Biblical Hebrew: An Intermediate Textbook* · Ehud Ben Zvi, Maxine Hancock, Richard A. Beinert · Yale University Press, 1993, 사무엘상 1:24 본문비평 설명(공개 발췌본 약 35쪽) · 출판사 저작권 자료이며 본 원고에 본문을 복제하지 않았습니다.\n   * 공식 서지: https://yalebooks.yale.edu/book/9780300055733/readings-in-biblical-hebrew/\n   * 확인한 발췌본: https://drupal.yalebooks.yale.edu/sites/default/files/files/Media/9780300055733_Zvi_Readings%20in%20Biblical%20Hebrew/9780300055733_Excerpt.pdf\n* “Was Samuel Meant to Be a Nazirite? The First Chapter of Samuel and the Paradigm Shift in Textual Study of the Hebrew Bible” · Anneli Aejmelaeus · *Textus* 28/1 (2019), 1–20, DOI 10.1163/2589255X-02801001 · 서원과 본문 전승에 관한 공개 초록을 참조하였습니다. 학술지 저작권 조건은 별도 확인 대상입니다.\n   * 학술지 공식 초록·서지: https://brill.com/view/journals/text/28/1/article-p1_1.pdf\n   * 논문 전체를 직접 정독한 것으로 표시하지 않으며, 확인한 초록 범위의 논지만 사용하였습니다.","연구 및 재서술 안내","이 글은 사무엘상 1:21–28의 히브리어 본문을 직접 대조하고, 기존 WORBS 사무엘상 1장 연구의 문학적 흐름과 해석을 재사용하여 독자용 한국어 산문으로 재구성한 것입니다. 실제 확인한 공개 학술 발췌본과 논문 초록은 본문비평상 중요한 차이를 설명하는 데 한정하여 참고하였습니다. 원어 설명은 문맥에 맞게 한국어로 풀어썼으며, 기존 연구와 이 글의 독립·파생 저작물 분류는 권리 검토 없이 확정하지 않습니다.","라이선스","원천별 권리 조건은 서로 다릅니다. OSHB의 표제어·형태 분석은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)을 따르며, 기반 WLC 본문은 Public Domain입니다. 대한성서공회의 한국어 성경, 기존 WORBS 연구, Yale University Press의 학술 발췌본 및 *Textus* 논문은 각 권리자의 조건을 따릅니다. CC BY-SA 4.0 자료를 사용하지 않았으므로 해당 라이선스를 이 원고에 적용하지 않습니다. 원고 전체에 적용할 단일 라이선스와 공개 재배포 권한은 별도로 검증해야 합니다."],"sourceNotice":"연구 참고자료\n\n* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:21–28 및 연결 본문 대조 · 저작권자: 대한성서공회. 공개 재배포 허락은 별도 확인이 필요합니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.1.21–28 히브리어 본문·표제어·형태 분석 · 형태·표제어 자료 CC BY 4.0; 기반 Westminster Leningrad Codex(WLC) 본문 Public Domain.\n   * 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n   * 원저작 표시: Open Scriptures Hebrew Bible Project, https://github.com/openscriptures/morphhb\n   * 히브리어 어형과 문맥상 의미를 한국어 설명으로 재서술하였습니다. 원어 본문의 판본 자체를 수정하지 않았습니다.\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · 「WORBS_사무엘상1장_필터최소패치_v0.2」, 사무엘상 1:1–28 · 기존 연구 원고의 서술·문학 구조·정경 연결을 참조하였습니다. 권리 조건은 별도 확인 대상입니다.\n* *Readings in Biblical Hebrew: An Intermediate Textbook* · Ehud Ben Zvi, Maxine Hancock, Richard A. Beinert · Yale University Press, 1993, 사무엘상 1:24 본문비평 설명(공개 발췌본 약 35쪽) · 출판사 저작권 자료이며 본 원고에 본문을 복제하지 않았습니다.\n   * 공식 서지: https://yalebooks.yale.edu/book/9780300055733/readings-in-biblical-hebrew/\n   * 확인한 발췌본: https://drupal.yalebooks.yale.edu/sites/default/files/files/Media/9780300055733_Zvi_Readings%20in%20Biblical%20Hebrew/9780300055733_Excerpt.pdf\n* “Was Samuel Meant to Be a Nazirite? The First Chapter of Samuel and the Paradigm Shift in Textual Study of the Hebrew Bible” · Anneli Aejmelaeus · *Textus* 28/1 (2019), 1–20, DOI 10.1163/2589255X-02801001 · 서원과 본문 전승에 관한 공개 초록을 참조하였습니다. 학술지 저작권 조건은 별도 확인 대상입니다.\n   * 학술지 공식 초록·서지: https://brill.com/view/journals/text/28/1/article-p1_1.pdf\n   * 논문 전체를 직접 정독한 것으로 표시하지 않으며, 확인한 초록 범위의 논지만 사용하였습니다.\n\n연구 및 재서술 안내\n\n이 글은 사무엘상 1:21–28의 히브리어 본문을 직접 대조하고, 기존 WORBS 사무엘상 1장 연구의 문학적 흐름과 해석을 재사용하여 독자용 한국어 산문으로 재구성한 것입니다. 실제 확인한 공개 학술 발췌본과 논문 초록은 본문비평상 중요한 차이를 설명하는 데 한정하여 참고하였습니다. 원어 설명은 문맥에 맞게 한국어로 풀어썼으며, 기존 연구와 이 글의 독립·파생 저작물 분류는 권리 검토 없이 확정하지 않습니다.\n\n라이선스\n\n원천별 권리 조건은 서로 다릅니다. OSHB의 표제어·형태 분석은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)을 따르며, 기반 WLC 본문은 Public Domain입니다. 대한성서공회의 한국어 성경, 기존 WORBS 연구, Yale University Press의 학술 발췌본 및 *Textus* 논문은 각 권리자의 조건을 따릅니다. CC BY-SA 4.0 자료를 사용하지 않았으므로 해당 라이선스를 이 원고에 적용하지 않습니다. 원고 전체에 적용할 단일 라이선스와 공개 재배포 권한은 별도로 검증해야 합니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_01_09_20_WORBS_READER_DRAFT_20261018","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/1SA_01_09_20_WORBS_READER_DRAFT_20261018.md","sourceSha256":"6c88c2f387bb95e9f6fb2a1af0434d0d7dda3b7614d2f07c0aff4582bb41cefc","passage":{"book":"1sa","chapter":1,"v1":9,"v2":20,"ref":"사무엘상 1:9–20"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"# 눈물에서 기억하심으로","overview":["실로 성소에서의 식사와 가족 갈등을 보여 준 앞 단락(1:1–8)에 이어, 한나는 일어나 여호와께 자신의 괴로운 마음을 아룁니다. 그는 아들을 구하면서도 그 아들을 평생 여호와께 드리겠다고 서원합니다. 그러나 기도하는 입술만 보고 엘리는 한나를 술 취한 사람으로 오해합니다. 한나가 자신을 설명하자 엘리는 평안을 빌고, 한나는 아직 아무 결과도 확인하지 못한 채 식사를 다시 시작합니다. 이튿날 가족은 예배를 드린 뒤 집으로 돌아가고, 서술자는 여호와께서 한나를 기억하셨다고 전합니다. 마침내 아들이 태어나고 한나는 그 이름을 사무엘이라 부릅니다."],"centralMessage":"이 단락의 전환점은 한나가 간절히 기도했다는 사실만이 아니라, 그 기도가 향하는 여호와께서 그를 기억하셨다는 서술에 있습니다. 한나의 고통은 성급히 지워지지 않으며, 성소의 제사장조차 그를 처음에는 알아보지 못합니다. 그러나 한나는 자신의 삶을 하나님 앞에 숨기지 않고 말하며, 하나님께 받은 생명을 자신의 소유로만 붙잡지 않겠다고 약속합니다. 개인의 간구와 하나님의 기억하심이 만나는 이 이야기는 뒤에 이스라엘의 말씀과 왕권의 역사를 이끌 사무엘의 출생을 준비합니다.","literaryStructure":[{"v1":9,"v2":10,"title":"한나가 일어나고 성소의 문턱이 보인다"},{"v1":11,"v2":11,"title":"‘보시고 기억하소서’라는 서원"},{"v1":12,"v2":14,"title":"입술은 움직이지만 소리는 들리지 않는다"},{"v1":15,"v2":16,"title":"‘내 마음을 쏟아 놓았습니다’라는 해명"},{"v1":17,"v2":18,"title":"결과보다 먼저 찾아온 식사와 얼굴의 변화"},{"v1":19,"v2":20,"title":"예배를 마치고 돌아간 자리에서 하나님이 기억하신다"}],"sections":[{"id":"1sa1-9-10","v1":9,"v2":10,"title":"한나가 일어나고 성소의 문턱이 보인다","paragraphs":["앞 단락에서 한나는 울며 먹지 못했고, 남편 엘가나의 애정 어린 질문도 그 고통을 해결하지 못했다(1:7–8). 9절의 첫 동사, ‘일어났다’는 말은 정지해 있던 장면을 움직입니다. 이제 이야기는 가족의 대화에서 한나 자신의 행동으로 중심을 옮깁니다. 한나가 무엇을 먹었는지에 관해서는 번역상의 표현 차이가 있을 수 있지만, 여기서 중요한 것은 식사가 끝난 뒤 한나가 성소에서 기도의 자리로 나아간다는 사건의 순서입니다.","서술자는 엘리 제사장이 여호와의 성전 문설주 곁 의자에 앉아 있다고 덧붙입니다. ‘성전’에 해당하는 히브리어 헤칼(הֵיכָל)은 이 장면에서 실로의 거룩한 건물을 가리킵니다. 이를 곧바로 훗날 솔로몬이 지은 예루살렘 성전과 동일한 건축 형태로 이해할 필요는 없습니다. 본문은 엘리의 위치와 성소의 문턱을 보여 주지만, 건물의 세부 평면이나 당시 실로의 모든 시설을 재구성할 정보까지 주지는 않습니다. 성소의 문턱은 뒤이어 한나의 기도를 지켜보는 엘리의 시선을 준비하는 문학적 장치이기도 합니다.","10절은 한나가 ‘마음이 괴로워’ 여호와께 기도하고 크게 운다고 기록합니다. 히브리어 마라트 네페쉬(מָרַת נָפֶשׁ)는 단순히 잠시 기분이 상했다는 뜻이 아니라, 존재의 깊은 곳까지 쓰라린 상태를 표현합니다. 한나의 기도는 고통이 사라진 뒤 시작된 경건한 절차가 아닙니다. 바로 그 고통 속에서 여호와를 향한 말이 시작됩니다. 이 점에서 이야기는 인간의 감정을 부정하지 않으면서도, 그 감정이 하나님과의 관계 안에서 발화되는 과정을 보여 줍니다."]},{"id":"1sa1-11-11","v1":11,"v2":11,"title":"‘보시고 기억하소서’라는 서원","paragraphs":["한나의 말은 ‘만군의 여호와’를 부르는 데서 시작합니다. 앞 단락에서 가족이 해마다 예배하던 바로 그 하나님께 이제 한나가 자기 사정을 직접 말합니다. 그가 먼저 구하는 것은 즉각적인 해결책의 기술이 아니라, 하나님이 자신의 고통을 보시고 자신을 기억하시며 잊지 않으시는 일입니다. 히브리어의 ‘보시고 또 보신다면’(רָאֹה תִרְאֶה)은 같은 동사의 강조된 결합입니다. 이는 하나님이 한나의 현실을 참으로 주목해 주시기를 간청하는 절실함을 드러냅니다.","‘기억하소서’(זְכַרְתַּנִי)는 하나님이 정보를 잊어버렸다가 다시 떠올려야 한다는 뜻으로 읽기보다, 하나님이 한나의 처지를 돌보시고 행동해 주시기를 구하는 언어로 이해하는 것이 적절합니다. 창세기 8:1에서 하나님이 노아를 기억하신 뒤 홍수의 물이 물러가고, 출애굽기 2:24에서 하나님이 언약을 기억하신 뒤 이스라엘의 구원 이야기가 전개되는 것과 비교할 수 있습니다. 다만 이 평행 본문들이 한나의 기도를 기계적으로 재현한다는 뜻은 아닙니다. ‘기억’이라는 표현이 하나님의 실제적인 돌보심과 연결된다는 정경적 공명을 보여 줍니다.","한나는 아들을 달라고 구하면서 그를 평생 여호와께 드리고 머리에 삭도를 대지 않겠다고 서원합니다. ‘아들’을 뜻하는 표현은 히브리어로 ‘남자의 씨’에 가까운 말이지만, 여기서는 남자아이를 구하는 뜻으로 이해됩니다. 한나는 자신이 얻기를 간절히 원하는 존재를 자신의 삶에 영구히 붙들어 두겠다고 말하지 않습니다. 아직 받지 않은 아들을 하나님께 속한 삶으로 드리겠다는 약속이 청원과 함께 놓입니다. 이것을 고통 없는 모범적 헌신으로 미화할 수는 없습니다. 아이를 원한다는 소망과 아이를 하나님께 드리겠다는 결단 사이의 긴장이 바로 서원의 무게입니다.","삭도를 대지 않겠다는 말은 민수기 6장의 나실인 규례 및 사사기 13장의 삼손 이야기와 관련하여 읽을 수 있습니다. 그러나 사무엘상 1:11의 히브리어 본문 자체는 나실인이라는 명칭을 사용하거나 모든 나실인 규정을 열거하지 않습니다. 따라서 사무엘의 봉헌이 나실인적 성격을 띤다고 설명하는 것과 그가 특정 규례의 모든 조항을 그대로 따랐다고 확정하는 것은 구별해야 합니다."]},{"id":"1sa1-12-14","v1":12,"v2":14,"title":"입술은 움직이지만 소리는 들리지 않는다","paragraphs":["기도가 길어지는 동안 엘리는 한나의 입을 지켜봅니다. 한나는 마음속으로 말하고 입술만 움직였으므로 소리가 들리지 않습니다. 서술자는 독자에게 이미 한나의 기도 내용을 알려 주었지만, 엘리는 그 내용을 듣지 못합니다. 독자가 아는 것과 등장인물이 아는 것 사이의 차이가 오해를 낳는 장면입니다. 엘리는 한나를 술 취한 사람으로 판단하고 언제까지 취해 있겠느냐고 꾸짖습니다.","본문은 엘리가 왜 그런 추정을 했는지 그의 내면을 설명하지 않습니다. 당시 예배의 구체적 관습을 모두 알 수 있는 것도 아닙니다. 따라서 이 한 장면만으로 고대 이스라엘에서 소리 없는 기도가 금지되었다고 단정할 수 없습니다. 분명한 것은 엘리의 판단이 틀렸다는 사실입니다. 그가 성소의 제사장으로 앉아 있어도 한나의 속마음을 제대로 보지 못합니다. 성소 안의 종교적 권위와 실제 고통을 분별하는 능력이 반드시 일치하지 않음을 이 장면은 보여 줍니다.","엘리를 이 순간부터 전적으로 악한 인물로 그리는 것도 본문보다 앞서가는 해석입니다. 뒤에서 그는 한나의 설명을 듣고 평안을 빌어 준다(17절). 다만 그의 첫 판단이 고통받는 사람을 더 상하게 할 수 있는 오해였다는 점은 가볍게 넘어갈 수 없습니다. 사무엘상 2장에서 드러나는 엘리 집안의 문제는 이 장면을 다시 생각하게 하지만, 후속 서술의 모든 평가를 1:13–14에 한꺼번에 덧씌우지 않는 편이 정확합니다."]},{"id":"1sa1-15-16","v1":15,"v2":16,"title":"‘내 마음을 쏟아 놓았습니다’라는 해명","paragraphs":["한나는 제사장에게 거칠게 맞서거나 자신의 기도를 철회하지 않습니다. 자신은 술이나 독주를 마신 사람이 아니라 ‘마음이 괴로운 여자’라고 설명합니다. 앞서 서술자가 알려 준 고통의 실체를 이제 한나 자신의 입으로 듣게 되는 것입니다. 한나가 사용한 ‘내 영혼을 쏟아 놓았다’(וָאֶשְׁפֹּךְ אֶת־נַפְשִׁי)는 표현은 감정을 조금 드러냈다는 뜻보다 자신의 깊은 내면을 여호와 앞에 남김없이 내어 놓았다는 뜻을 전합니다. ‘영혼’이라는 말은 몸과 분리된 어떤 부분만을 가리킨다기보다, 고통을 겪는 한 사람의 생명과 자아를 폭넓게 나타냅니다.","16절에서 한나는 자신을 ‘불량한 여자’로 여기지 말라고 부탁합니다. 여기의 ‘벨리알의 딸’에 해당하는 표현은 도덕적으로 불량한 사람을 가리키는 관용적 말로 이해할 수 있습니다. 이 표현은 2장에서 엘리의 아들들을 ‘불량자들’로 묘사하는 말과 연결되어 의미심장한 대조를 만듭니다. 한나는 그런 사람으로 오해받지만, 이어지는 이야기는 오히려 제사장 집안의 행실에 문제를 제기합니다. 다만 이 대비를 보려면 2장의 후속 설명이 필요하며, 1:16 자체가 이미 엘리의 아들들에 대한 완전한 판결을 제시하는 것은 아닙니다.","한나는 자신의 말이 ‘많은 원통함과 격분’에서 나왔다고 설명합니다. 이는 기도가 마음을 억지로 평온하게 만드는 형식이 아니라, 실제 원통함을 하나님께 말하는 행위임을 보여 줍니다. 한나가 서원을 했다는 사실이 그 고통의 크기를 줄이지 않습니다. 오히려 본문은 기도의 진실성과 슬픔의 깊이를 함께 보존합니다."]},{"id":"1sa1-17-18","v1":17,"v2":18,"title":"결과보다 먼저 찾아온 식사와 얼굴의 변화","paragraphs":["엘리는 한나의 말을 듣고 ‘평안히 가라’고 하며 이스라엘의 하나님께서 그의 구한 것을 주시기를 빕니다. 그의 첫 말은 잘못된 단정이었지만, 이번에는 한나를 고발하는 대신 축복의 말로 보냅니다. 엘리의 말은 문법상 하나님이 한나의 청원을 이루어 주시기를 바라는 축복으로 읽을 수 있습니다. 이를 그가 미래의 임신을 이미 확실히 알았다는 선언으로 확대할 근거는 본문에 없습니다.","한나는 제사장 앞에서 은혜를 입기를 바란다고 답하고 돌아가 음식을 먹습니다. 그 얼굴은 더 이상 전과 같지 않다고 기록됩니다. 앞 단락에서 한나는 울며 먹지 못했다(7절). 이제 서술은 같은 ‘먹음’의 소재를 사용해 변화를 보여 줍니다. 중요한 것은 아직 19–20절의 출생 사건이 일어나지 않았다는 사실입니다. 따라서 그의 변화는 이미 아들을 안았기 때문에 생긴 기쁨이 아니라, 하나님 앞에 마음을 쏟고 축복의 말을 들은 뒤 나타난 변화입니다.","이 장면을 모든 기도가 반드시 원하는 결과를 얻는다는 보증으로 일반화해서는 안 됩니다. 본문은 한나에게 일어난 특정한 사건을 말합니다. 동시에 이야기는 응답이 눈에 보이기 전에도 사람의 태도와 얼굴에 변화가 나타날 수 있다는 서사적 사실을 놓치지 않습니다. ‘먹지 못함’에서 ‘먹음’으로의 전환은 이 단락의 섬세한 문학적 표지입니다."]},{"id":"1sa1-19-20","v1":19,"v2":20,"title":"예배를 마치고 돌아간 자리에서 하나님이 기억하신다","paragraphs":["이튿날 가족은 일찍 일어나 여호와 앞에 경배하고 라마의 집으로 돌아갑니다. 본문은 실로에서 라마로의 귀환을 말하지만, 세부 경로와 이동 거리, 도중의 정착지까지 알려 주지는 않습니다. 앞 단락의 연례 순례와 마찬가지로 지리적 정보는 출발과 귀환의 관계를 밝히는 범위에서 읽는 것이 타당합니다. 이어 엘가나와 한나의 부부 관계가 간략히 언급된 뒤, ‘여호와께서 그를 기억하셨다’는 결정적인 문장이 놓입니다.","이 문장은 11절의 간구에 대한 서사적 응답입니다. 한나는 ‘기억하소서’라고 청했고, 서술자는 여호와께서 ‘기억하셨다’고 말합니다. 출생을 향한 인간의 삶의 과정은 지워지지 않지만, 화자는 그 과정 위에 하나님의 돌보심을 놓습니다. 기도의 성취를 한나의 말 자체가 지닌 어떤 힘으로 설명하기보다, 그 기도를 들으시는 하나님에게 중심을 둡니다. 이는 앞 단락에서 여호와께서 한나의 태를 닫으셨다는 서술(5–6절)과도 긴장 속에 연결됩니다. 본문은 하나님의 주권을 말하면서도 한나의 고통을 죄의 벌로 규정하지 않습니다.","‘때가 이르매’에 해당하는 표현은 시간이 흘렀음을 알려 줄 뿐, 임신과 출산의 정확한 연월일을 제공하지 않습니다. 한나는 아들을 낳고 ‘사무엘’이라는 이름을 붙이며 여호와께 구하여 얻었다고 말합니다. 여기서 ‘구하다’(שָׁאַל, 샤알)라는 동사는 엘리의 축복에 나타난 청원(17절)과 연결되고, 뒤의 봉헌 장면(27–28절)에서 다시 중요한 역할을 합니다. 사무엘이라는 이름의 엄밀한 어원이 이 동사에서 직접 만들어졌다고 단정하기는 어렵습니다. 본문은 이름의 언어학적 기원만 설명하기보다, 한나가 그 아이를 ‘여호와께 구한 아들’로 이해한다는 신앙적 의미를 강조합니다.","이렇게 1:9–20은 고통에서 기도로, 오해에서 해명으로, 눈물에서 식사로, 간구에서 기억하심과 출생으로 나아갑니다. 그러나 이야기는 출생으로 완전히 끝나지 않습니다. 한나가 약속한 봉헌이 1:21–28에서 이루어지고, 2:1–10의 노래는 개인의 경험을 낮은 자를 높이시는 하나님의 통치로 확장합니다. 독자는 지금 이 출생의 기쁨을 보면서도, 아이를 여호와께 드리겠다는 서원이 아직 남아 있음을 기억하게 됩니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"강조된 ‘보다’와 응답하는 ‘기억하다’","paragraphs":["11절의 רָאֹה תִרְאֶה는 히브리어 부정사 절대형과 활용 동사가 결합한 강조 표현입니다. 이를 한국어에서 같은 동사를 두 번 기계적으로 반복할 필요는 없으며, ‘참으로 살펴보신다면’처럼 간청의 강도를 드러낼 수 있습니다. 11절의 זְכַרְתַּנִי와 19절의 וַיִּזְכְּרֶהָ는 ‘기억’이라는 같은 동사 어근을 사용해 청원과 응답을 연결합니다. 이는 단어 하나의 신비한 효력보다 서술 전체의 연결을 이해하게 하는 중요한 관찰입니다."]},{"title":"서원과 나실인 규례의 관계","paragraphs":["삭도를 대지 않겠다는 11절의 말은 민수기 6:1–21의 나실인 규례 및 사사기 13:5의 삼손 출생 예고를 떠올리게 합니다. 그러나 마소라 본문에 나타나는 명시 사항은 평생의 봉헌과 머리털에 관한 약속입니다. 고대 그리스어 역본에서는 금주와 관련한 추가 표현이 전해지는 것으로 알려져 있으나, 이 원고는 그 역본의 특정 사본을 직접 대조한 판본비평 결과를 제시하지 않습니다. 따라서 히브리어 본문이 말하는 범위와 역본 전승에 대한 추가 검증이 필요한 범위를 구별해야 합니다."]},{"title":"성소의 기도와 엘리의 오해","paragraphs":["한나의 입술은 움직였으나 음성은 들리지 않았다(13절). 이 구체적인 묘사는 기도의 방식 자체에 대한 보편적 규정이라기보다, 엘리가 관찰할 수 있는 것과 한나가 실제로 하고 있는 일 사이의 차이를 드러냅니다. 그의 판단은 정정되고 축복으로 바뀌지만, 이 사건 하나만으로 엘리의 모든 사역을 평가할 수는 없습니다. 2:12 이하의 엘리 아들들에 관한 서술과 함께 읽을 때 성소의 권위와 신실함의 관계가 더욱 복잡해집니다."]},{"title":"‘벨리알의 딸’과 후속 장면의 대조","paragraphs":["16절의 בַּת־בְּלִיַּעַל은 ‘무가치함·불량함’과 관련된 관용 표현입니다. 한나는 그런 사람으로 취급받지 않기를 구합니다. 2:12에서는 엘리의 아들들이 유사한 표현으로 묘사됩니다. 독자는 오해받은 한나와 실제로 제사를 멸시하는 자들 사이의 대조를 읽을 수 있지만, 이것은 인접 본문을 함께 읽을 때 드러나는 문학적 관찰이지 1:16 한 절만의 명시적 설명은 아닙니다."]},{"title":"사무엘 이름의 해석과 정경적 위치","paragraphs":["20절의 설명은 ‘내가 여호와께 그를 구하였다’는 한나의 말에 초점이 있습니다. 히브리어 שְׁמוּאֵל의 어원에 관해서는 여러 설명이 논의되어 왔으므로, 이야기 속 말놀이를 확정된 역사언어학적 어원으로 바꾸지 않습니다. 이후 사무엘은 이스라엘에서 말씀을 전하고 왕에게 기름을 붓는 인물이 된다(삼상 3장; 9–10장; 16장). 그러므로 그의 출생은 개인적 기도 응답이면서 왕정 전환의 서론이라는 정경적 의미를 갖습니다. 다만 1:9–20 자체에는 아직 사울이나 다윗의 즉위 사건이 나오지 않습니다."]}],"relatedResearch":[],"readerSources":[],"notes":["연구 참고자료","* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:9–20 및 연결 본문 · 대한성서공회 저작권. 공개 재배포 허락은 별도 확인이 필요합니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.1.9–20, 원문 및 형태 분석 · CC BY 4.0. 기반 히브리어 본문 Westminster Leningrad Codex(WLC)는 Public Domain입니다.\n   * Original work of the Open Scriptures Hebrew Bible available at https://github.com/openscriptures/morphhb\n   * 사용 판본 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · 사무엘상 1:1–28, 2026년 7월 개정 연구 원고 v0.2 · 저작권 및 외부 이용 조건은 별도 확인 대상입니다.","연구 및 재서술 안내","이 글은 사무엘상 1장 WORBS 기존 연구의 문학적 구조와 주해를 참조하고, 사무엘상 1:9–20의 히브리어 본문을 다시 살피며 독자용 한국어 문장으로 재구성하였습니다. 히브리어의 짧은 뜻풀이는 본문의 문맥을 설명하기 위해 한국어로 새로 서술하였습니다. 기존 연구와의 관계가 독립 저작물인지 파생 저작물인지는 별도의 권리 검토 없이 단정하지 않습니다.","라이선스","원천별 조건은 서로 다릅니다. OSHB의 형태 분석 자료는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)에 따르며, 기반 WLC 히브리어 본문은 Public Domain입니다. 대한성서공회의 한국어 성경 본문과 기존 WORBS 연구의 권리는 각 권리자의 조건을 따릅니다. 이 원고 전체에 적용할 단일 라이선스와 외부 배포 권한은 아직 확정하지 않았습니다."],"sourceNotice":"연구 참고자료\n\n\n* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:9–20 및 연결 본문 · 대한성서공회 저작권. 공개 재배포 허락은 별도 확인이 필요합니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.1.9–20, 원문 및 형태 분석 · CC BY 4.0. 기반 히브리어 본문 Westminster Leningrad Codex(WLC)는 Public Domain입니다.\n   * Original work of the Open Scriptures Hebrew Bible available at https://github.com/openscriptures/morphhb\n   * 사용 판본 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · 사무엘상 1:1–28, 2026년 7월 개정 연구 원고 v0.2 · 저작권 및 외부 이용 조건은 별도 확인 대상입니다.\n\n\n연구 및 재서술 안내\n\n\n이 글은 사무엘상 1장 WORBS 기존 연구의 문학적 구조와 주해를 참조하고, 사무엘상 1:9–20의 히브리어 본문을 다시 살피며 독자용 한국어 문장으로 재구성하였습니다. 히브리어의 짧은 뜻풀이는 본문의 문맥을 설명하기 위해 한국어로 새로 서술하였습니다. 기존 연구와의 관계가 독립 저작물인지 파생 저작물인지는 별도의 권리 검토 없이 단정하지 않습니다.\n\n\n라이선스\n\n\n원천별 조건은 서로 다릅니다. OSHB의 형태 분석 자료는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)에 따르며, 기반 WLC 히브리어 본문은 Public Domain입니다. 대한성서공회의 한국어 성경 본문과 기존 WORBS 연구의 권리는 각 권리자의 조건을 따릅니다. 이 원고 전체에 적용할 단일 라이선스와 외부 배포 권한은 아직 확정하지 않았습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_02_01_10_WORBS_READER_DRAFT_20261020","researchType":"WORBS","researchDepth":"CORE","sourcePath":"C:/Users/언약의~1/AppData/Local/Temp/claude/C--Users--------codex-worktrees-judebible-runtime-integration---/9427b599-5413-43f5-8bb9-3682554439fe/scratchpad/1sa2-copies/1SA_02_01_10_WORBS_READER_DRAFT_20261020.md","sourceSha256":"45c0852dbec15cdafaff1f891d6988eba3d1bf592658714001ba0bfed3c53d12","passage":{"book":"1sa","chapter":2,"v1":1,"v2":10,"ref":"사무엘상 2:1–10"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"높아진 뿔에서 기름부음 받은 왕까지","overview":["한나는 오래 기다려 얻은 사무엘을 실로에 데려와 여호와께 드렸다(1:21–28). 이제 이야기는 아이를 맡기는 행동에서 한나의 기도로 옮겨 갑니다. 그런데 그 기도는 아들의 출생을 감사하는 짧은 말로 끝나지 않습니다. 한나는 자신을 낮은 자리에서 일으키신 하나님이 교만한 자를 낮추고 약한 자를 높이며, 마침내 온 땅을 판단하고 자기 왕에게 힘을 주실 분이라고 노래합니다. 한 가정에서 일어난 변화가 하나님이 세상을 다스리시는 방식에 대한 고백으로 넓어집니다.","노래의 처음과 끝에는 '뿔을 높이신다'는 표현이 놓여 있습니다. 처음에는 한나 자신의 뿔이 여호와 안에서 높아지고(1절), 끝에서는 하나님의 기름부음 받은 자의 뿔이 높아진다(10절). 뿔은 동물의 힘에서 나온 비유로, 여기서는 회복된 힘과 존엄을 나타냅니다. 한나의 기쁨은 개인의 승리를 과시하는 데 머무르지 않고, 힘의 주인이 누구인지 밝히는 데로 나아갑니다."],"centralMessage":"**이 노래의 중심은 사람의 높고 낮음이 마지막 판단 기준이 아니라는 사실입니다. 여호와께서는 인간의 자랑과 힘을 살피시고, 낮은 자를 일으키시며, 자신의 통치 아래 왕의 힘까지 결정하십니다.** 뒤이어 등장하는 엘리 집안의 실패와 사무엘의 성장, 사울과 다윗의 이야기는 이 노래가 미리 제시한 물음을 여러 장면에서 다시 들려줍니다.","literaryStructure":[{"v1":1,"v2":1,"title":"한나의 기쁨은 하나님에게서 시작된다"},{"v1":2,"v2":3,"title":"거룩한 반석 앞에서는 교만한 말이 가벼워진다"},{"v1":4,"v2":5,"title":"꺾인 활과 채워진 식탁, 뒤집히는 힘의 질서"},{"v1":6,"v2":7,"title":"생명과 죽음, 가난과 부요까지 노래의 시야가 넓어진다"},{"v1":8,"v2":9,"title":"먼지에서 일으키시는 하나님과 사람의 힘의 한계"},{"v1":10,"v2":10,"title":"노래는 한 사람의 구원에서 왕과 온 땅의 심판으로 나아간다"}],"sections":[{"id":"1sa2-1-1","v1":1,"v2":1,"title":"한나의 기쁨은 하나님에게서 시작된다","paragraphs":["사무엘상 1장의 마지막 장면에서 한나는 아들을 여호와께 드립니다. 그 뒤에 곧바로 이어지는 2장 1절은 '한나가 기도하여 말했다'고 소개합니다. 같은 인물이 다시 기도하지만, 기도의 목소리는 달라졌습니다. 1:10에서 한나는 마음이 괴로워 울며 기도했고, 1:15에서는 자신의 마음을 여호와 앞에 쏟아 놓았다고 설명했습니다. 이제는 그 마음이 여호와 안에서 기뻐한다고 노래합니다. 두 기도를 이어 읽을 때, 고통이 없었던 것처럼 지워지는 것이 아니라 고통 속에서 드린 청원이 새로운 찬양으로 이어졌음을 보게 됩니다.","히브리어 동사 '알라츠'(עָלַץ)는 마음이 크게 기뻐하거나 환희에 차는 모습을 전합니다. 한나는 기쁨의 이유를 단지 '아들이 생겼기 때문'이라고만 말하지 않고 거듭 '여호와 안에서'라고 표현합니다. 아들을 얻은 일은 분명 이 기쁨의 역사적 계기입니다. 그러나 노래가 붙드는 중심은 선물을 주신 하나님입니다. 그러므로 이 기도를 한나가 자신을 괴롭혔던 사람보다 더 높은 자리에 올랐다는 경쟁의 결말로 읽으면, 노래가 앞으로 나아가는 방향을 좁히게 됩니다.","'내 뿔이 높아졌다'는 말은 오늘날에는 낯설지만 고대 시의 세계에서는 힘과 명예를 나타내는 생생한 그림입니다. 뿔을 높이 든 짐승의 모습에서 힘이 회복되고 수치가 벗겨지는 이미지를 떠올릴 수 있습니다. 이 말은 한나가 실제로 뿔을 가지고 있다는 뜻도, 어떤 정치적 지위를 얻었다는 뜻도 아닙니다. 그동안 사람들 앞에서 고개를 들기 어려웠던 상황이 여호와의 구원으로 달라졌다는 시적 표현입니다. 마지막 10절에서 같은 뿔의 이미지가 왕에게로 옮겨 가기 때문에, 첫 구절의 비유는 노래 전체를 읽는 실마리가 됩니다.","한나는 자신의 입이 원수들을 향해 크게 열렸다고 말합니다. 1장에서 브닌나가 한나를 괴롭혔다는 사실을 기억하면, 이 말에는 이전의 모욕과 침묵이 뒤집힌 배경이 있습니다. 그러나 노래는 브닌나의 이름을 다시 부르지 않습니다. 한나가 실제로 누구에게 어떤 말을 되돌려주었는지도 기록하지 않습니다. 본문이 보여 주는 것은 여호와의 구원을 기뻐하는 목소리가 이제 열렸다는 사실입니다. '구원'에 해당하는 히브리어 '예슈아'(יְשׁוּעָה)는 여기서 먼저 한나가 경험한 건짐과 회복을 가리킵니다. 이후 노래가 넓어지면서 그 구원은 하나님의 통치와 심판이라는 더 큰 시야 안에 놓입니다."]},{"id":"1sa2-2-3","v1":2,"v2":3,"title":"거룩한 반석 앞에서는 교만한 말이 가벼워진다","paragraphs":["기쁨을 노래한 한나는 곧 하나님의 성품을 말합니다. 여호와처럼 거룩한 분이 없고, 그분과 같은 반석도 없다고 합니다. '거룩하다'는 말은 단순히 사람이 도덕적으로 흠이 없다는 표현을 하나님께 크게 적용한 정도가 아닙니다. 여기서는 여호와를 다른 어떤 존재와도 나란히 놓을 수 없다는 고백입니다. 한나를 기억하신 하나님은 그때만 잠시 힘을 발휘한 분이 아니라, 비교할 수 없는 분이십니다.","'반석'(צוּר, 추르)은 단단하고 흔들리지 않는 바위에서 가져온 비유입니다. 한나가 이 단어로 실로 주변의 특정 지형을 설명하는 것은 아닙니다. 앞서 그가 경험한 삶의 불안정함과 대조하여, 의지할 수 있는 하나님의 신실함을 노래하는 말입니다. 사무엘서 뒤쪽에서 다윗도 여호와를 반석이라고 부른다(삼하 22:2–3, 32). 두 노래는 서로 다른 역사적 자리에서 같은 하나님을 고백합니다. 이것은 두 노래를 동일한 사건으로 만드는 연결이 아니라, 사무엘서가 반복하여 들려주는 하나님 이해의 연속성입니다.","이어서 한나는 갑자기 청중을 향해 말합니다. 교만한 말을 거듭하지 말고 입에서 오만한 말을 내지 말라고 합니다. 1장의 가족 갈등이 떠오르지만, 노래는 특정 사람을 직접 지목하는 데서 멈추지 않습니다. 자신이 가진 자녀와 힘을 근거로 다른 사람을 내려다보는 태도 전체가 이 경고 앞에 놓입니다. 1절에서 한나의 입이 열렸다면, 3절에서는 자랑하는 자들의 입이 제지됩니다. 같은 '말'의 영역에서 구원을 찬양하는 발화와 자신을 높이는 발화가 선명하게 대비됩니다.","그 이유는 여호와께서 '지식의 하나님'이시기 때문입니다. 히브리어는 '지식들'(דֵּעוֹת)이라는 복수 형태를 사용하여 하나님이 아시는 범위를 강조합니다. 뒤이어 나오는 '행동을 달아 보신다'는 이미지는 사람이 내세우는 말과 실제 행위를 하나님이 판단하신다는 뜻으로 읽힙니다. 이 말은 고난당하는 사람에게 하나님이 모든 고통의 이유를 설명해 주셨다는 주장이 아닙니다. 오히려 사람은 눈에 보이는 조건으로 다른 사람을 평가하지만, 하나님은 사람의 행동을 제대로 살피신다는 노래의 논리를 세웁니다. 이후 엘리의 아들들이 거룩한 직분을 가졌으면서도 여호와를 알지 못한다고 평가받는 장면(2:12–17)은 이 기준을 구체적으로 드러냅니다."]},{"id":"1sa2-4-5","v1":4,"v2":5,"title":"꺾인 활과 채워진 식탁, 뒤집히는 힘의 질서","paragraphs":["한나는 이제 서로 반대되는 장면들을 짧은 행으로 이어 놓습니다. 용사들의 활은 꺾이고, 넘어졌던 사람들은 힘으로 허리를 동입니다. 배부르던 사람들은 먹을 것을 얻으려고 품을 팔고, 굶주리던 사람들은 더 이상 굶주리지 않습니다. 여기서 활은 전쟁에서 힘을 발휘하는 도구이며, 먹을 것은 일상에서 생존을 좌우하는 조건입니다. 시는 군사적 힘과 경제적 여유를 나란히 놓아, 사람들이 흔히 안전하다고 여기는 두 가지 기반이 영원하지 않다고 말합니다.","이 대조를 읽을 때 한쪽은 언제나 악하고 다른 쪽은 언제나 선하다고 자동으로 나눌 수는 없습니다. 노래의 초점은 가난 자체를 미화하거나 부요 자체를 죄로 규정하는 데 있지 않습니다. 3절의 교만한 말과 행동의 평가가 앞에 놓였기 때문에, 인간이 자신의 강함을 절대적인 것으로 여기지 못하게 하는 데 의미가 있습니다. 힘이 있다는 사실이 최종적인 안전을 보장하지 않고, 약하다는 사실이 하나님 앞에서 영원한 패배를 뜻하지 않습니다.","다음 대조는 한나 자신의 삶에 더욱 가까워집니다. 아이를 낳지 못하던 여인이 일곱을 낳고, 자녀가 많던 여인은 쇠약해진다고 노래합니다. 사무엘의 출생을 알고 있는 독자는 한나가 왜 이 그림을 선택했는지 이해할 수 있습니다. 그러나 '일곱'을 그가 이 시점에 실제로 낳은 자녀의 숫자로 읽으면 본문의 시간을 혼동합니다. 뒤에서 한나에게 세 아들과 두 딸이 더 태어났다는 서술(2:21)을 사무엘과 합쳐도 여섯입니다. 이 시의 '일곱'은 풍성함과 충만함을 그리는 시적 숫자로 읽는 것이 자연스럽습니다. 정확한 자녀 수를 보고하는 족보가 아니라, 수치와 결핍이 뒤집히는 장면을 노래하는 것입니다.","이렇게 보면 한나의 경험은 단지 개인적인 행복의 근거로 사용되지 않습니다. 자녀의 유무로 사람의 가치를 평가하던 현실에서, 그는 그 평가가 얼마나 불안정한지를 노래합니다. 동시에 본문은 모든 불임의 경험이 한나와 똑같은 결과로 끝난다는 약속을 제시하지 않습니다. 시가 말하는 것은 특정한 사건에서 드러난 여호와의 능력과, 인간의 조건을 최종 판결로 삼을 수 없다는 더 넓은 진실입니다. 개인의 기억이 세상을 바라보는 언어로 바뀌는 대목입니다."]},{"id":"1sa2-6-7","v1":6,"v2":7,"title":"생명과 죽음, 가난과 부요까지 노래의 시야가 넓어진다","paragraphs":["4–5절의 반전이 사람들 사이의 지위와 형편을 보여 주었다면, 6–7절은 그 변화를 가능하게 하시는 분을 반복하여 이름 부릅니다. '여호와께서'라는 주어가 앞에 놓이고, 죽이심과 살리심, 내리심과 올리심, 가난하게 하심과 부하게 하심, 낮추심과 높이심이 차례로 나옵니다. 서로 반대되는 동사들이 빠르게 교차하면서, 인간의 삶에서 가장 극단적으로 보이는 차이들까지 하나님의 주권 밖에 있지 않다는 사실을 노래합니다.","6절의 '스올'(שְׁאוֹל)은 고대 히브리어에서 죽은 자들의 영역을 가리키는 말입니다. 개역한글은 이를 '음부'로 옮깁니다. 한나의 노래는 여호와께서 스올에 내리게도 하시고 다시 올라오게도 하신다고 말합니다. 이 시적 평행법은 생사의 경계를 넘어서는 하나님의 권능을 강하게 고백합니다. 그러나 이 한 구절만으로 훗날 성경에서 더 자세히 드러나는 부활 교리의 모든 내용을 이미 완성된 형태로 설명했다고 보기는 어렵습니다. 우선 본문이 말하는 것은 죽음처럼 돌이킬 수 없어 보이는 영역도 하나님의 권능을 제한하지 못한다는 것입니다.","7절은 다시 생활의 언어로 돌아옵니다. 가난하게 하심과 부하게 하심, 낮추심과 높이심이 병행합니다. 여기서 '높이다'는 말은 1절에서 한나의 뿔이 높아졌다는 표현과 울림을 이룹니다. 한나의 변화가 우연한 행운으로 설명되지 않고 여호와의 통치 아래 이해되는 이유가 여기에 있습니다. 동시에 이 노래를 개별 사람의 가난이나 고난이 그 사람의 잘못에 대한 하나님의 직접 처벌이라는 공식으로 바꾸면, 1장에서 이유를 다 알 수 없는 고통을 겪던 한나의 이야기와 충돌합니다.","시의 문장들은 인생의 모든 경우를 일대일로 계산하는 규칙표가 아닙니다. 높고 낮음의 운명이 하나님 앞에 열려 있다는 신앙 고백입니다. 인간이 다른 사람의 처지를 보고 최종적인 결론을 내려 버릴 수 없다는 점에서, 이 시는 앞의 교만 경고와 계속 연결됩니다. 한나가 노래하는 하나님은 힘센 사람에게만 가까이 계신 분도, 약한 사람에게서 멀리 계신 분도 아닙니다. 그분의 주권은 인간의 분류보다 큽니다."]},{"id":"1sa2-8-9","v1":8,"v2":9,"title":"먼지에서 일으키시는 하나님과 사람의 힘의 한계","paragraphs":["8절은 앞의 '높이다'라는 말을 눈에 보이는 장면으로 펼칩니다. 하나님은 가난한 사람을 먼지에서 일으키시고, 궁핍한 사람을 거름더미에서 들어 올려 귀족들과 함께 앉게 하십니다. 이 이미지는 낮은 지위가 얼마나 낮게 취급될 수 있는지를 숨기지 않습니다. 사람의 삶을 떠받치는 자원과 존엄을 빼앗긴 자리에서, 여호와께서 새로운 자리를 주신다는 시적 그림입니다. 그가 누구를 어떻게 일으키시는지는 이야기마다 다르지만, 노래가 선포하는 원리는 같습니다. 현재의 서열이 하나님의 마지막 판결은 아닙니다.","'귀족들과 함께 앉는다'는 표현은 단순히 돈을 더 많이 갖게 된다는 말보다 넓습니다. 배제되던 사람이 존중받는 자리에 놓이는 모습입니다. 한나의 이야기를 떠올리면, 아이를 낳지 못한다는 이유로 괴롭힘을 받던 사람의 목소리가 지금은 하나님을 찬양하는 노래의 중심에 서 있습니다. 이 연결은 본문의 흐름에서 읽어 낼 수 있지만, 한나가 실제로 귀족의 의자에 앉았다는 사건을 만들어 내는 것은 아닙니다. 시는 자신의 경험을 넘어선 언어로 하나님의 역전을 그립니다.","8절 끝의 '땅의 기둥'은 고대 시가 세상을 지탱하는 기초를 말할 때 사용하는 우주적 이미지입니다. 이 표현은 지구의 물리적 구조를 과학적으로 설명하려는 문장이 아닙니다. 노래가 강조하는 것은 온 세계의 토대까지 여호와께 속한다는 점입니다. 따라서 그분이 낮은 사람을 높이시는 일은 세상의 일부에서 우연히 일어나는 예외가 아니라, 세계를 다스리시는 분의 행동으로 이해됩니다. 한나의 기도는 실로의 한 가정에서 시작했지만 이제 온 세계의 주인에게 이릅니다.","9절은 두 길을 대조합니다. 하나님은 자신에게 속한 사람들의 발걸음을 지키시고, 악인들은 어둠 속에서 잠잠하게 됩니다. '발'은 삶의 실제 걸음을 가리키는 구체적인 이미지입니다. 이 표현은 믿는 사람이 언제나 사고나 고통을 피한다는 보증서가 아닙니다. 이어지는 사무엘서에는 의로운 사람이 위험을 겪는 장면도 많습니다. 노래는 그들의 길이 궁극적으로 자기 힘에만 달려 있지 않다는 사실을 강조합니다.","이 단락의 결론은 사람이 힘만으로 이기지 못한다는 말입니다. 4절에서 꺾인 용사의 활이 여기서 다시 떠오릅니다. 인간의 힘은 실제로 존재하지만 그것이 하나님의 판단을 대신하지는 못합니다. 이 말은 사무엘상 뒤의 왕정 이야기에서 특히 중요해집니다. 사울의 외모와 군사적 지위, 다윗의 작은 출발과 그의 기름부음은 모두 어떤 힘이 참된 왕권을 세우는가 하는 질문 앞에 놓이기 때문입니다. 한나의 노래는 그 답을 인물들이 등장하기 전에 먼저 제시합니다."]},{"id":"1sa2-10-10","v1":10,"v2":10,"title":"노래는 한 사람의 구원에서 왕과 온 땅의 심판으로 나아간다","paragraphs":["마지막 절에서 시야는 다시 넓어집니다. 여호와를 대적하는 자들이 부서지고, 하나님이 하늘에서 우레를 내시며, 땅끝까지 판단하신다는 장면이 이어집니다. 3절에서 인간의 행동을 달아 보시는 하나님은 이제 온 땅의 심판자로 나타납니다. 노래의 첫머리에서는 한나가 자신을 괴롭힌 사람들 앞에서 입을 열었지만, 마지막에는 여호와를 대적하는 세력 전체가 하나님의 판단 아래 놓입니다. 개인의 경험에서 시작한 기도가 보편적인 통치의 고백으로 끝나는 것입니다.","그런데 마지막 문장은 새로운 대상을 부릅니다. 여호와께서 '자기 왕'에게 힘을 주시고 '자기의 기름부음 받은 자'의 뿔을 높이실 것이라고 합니다. '기름부음 받은 자'에 해당하는 히브리어 '메쉬아흐'(מָשִׁיחַ)는 기름부음을 받아 특정한 직무에 세워진 사람을 가리키는 말입니다. 이 자리에서는 바로 앞의 '왕'과 병행하므로 왕권의 언어로 읽는 것이 자연스럽습니다. '메시아'라는 후대의 신학적 의미를 생각하기 전에, 이 시가 먼저 말하는 것은 왕조차 스스로 힘의 근원이 될 수 없다는 사실입니다.","이 말은 사무엘상 2장 시점의 이야기 속에 아직 이스라엘 왕이 등장하지 않았다는 점에서 눈길을 끕니다. 독자는 뒤에서 사무엘이 사울에게 기름을 붓고(10:1), 이어 다윗에게도 기름을 붓는 장면(16:13)을 만나게 됩니다. 따라서 최종 형태의 사무엘서를 읽을 때 한나의 노래는 앞으로 전개될 왕정 이야기의 방향을 미리 알려 주는 서문처럼 기능합니다. 이것이 곧 한나가 후대 모든 정치적 사건의 세부를 알고 있었다는 뜻은 아닙니다. 노래의 본래 형성과 현재 이야기 속 배치를 구별하면서, 지금의 책이 독자에게 무엇을 들려주는지를 살피는 것이 중요합니다.","처음 1절에서 한나 자신의 '뿔'이 여호와 안에서 높아졌고, 끝 10절에서는 기름부음 받은 왕의 '뿔'이 높아집니다. 이 반복은 단순한 말의 장식이 아닙니다. 하나님께 받은 힘을 자기 것처럼 자랑하지 않는 한나의 기쁨과, 하나님의 판단 아래 있어야 할 왕의 힘을 한 문학적 틀 안에 놓습니다. 사무엘서가 왕의 능력과 실패를 계속 다루는 이유가 여기에서 예고됩니다. 왕이 있다는 사실보다, 그 왕이 누구에게 힘을 받고 누구의 통치 아래 서 있는가가 더 중요합니다.","사무엘하 22장에서 다윗이 여호와를 자신의 반석과 구원의 뿔로 찬양하고, 마지막에 하나님이 기름부음 받은 왕에게 베푸신 구원을 노래하는 장면(22:2–3, 51)은 한나의 노래와 강하게 호응합니다. 두 노래 사이에는 사무엘서의 긴 왕정 이야기가 놓입니다. 또한 시편 113:7–9는 가난한 자를 먼지에서 일으키시고 아이를 낳지 못하던 여인을 돌보시는 이미지를 공유합니다. 신약의 마리아 찬가(눅 1:46–55)는 낮은 자를 높이고 교만한 자를 흩으시는 하나님의 행동을 다시 찬양합니다. 이러한 연결은 후대 정경이 한나의 노래를 어떻게 더 넓게 듣게 하는지를 보여 주지만, 각각의 본문이 놓인 시대와 발화 상황을 지우지는 않습니다.","한나의 노래는 사무엘의 어린 시절을 장식하는 삽입 노래로만 남지 않습니다. 엘리의 아들들이 제사를 멸시하는 다음 장면, 어린 사무엘이 여호와 앞에서 자라는 장면, 그리고 왕을 세우고 평가하는 긴 이야기를 읽는 기준이 됩니다. **여호와의 거룩함과 판단이 인간의 힘을 재고, 낮은 자를 일으키며, 왕의 권위까지 그분에게서 나오게 한다는 고백**이 사무엘서 첫머리에 놓여 있는 것입니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"한나의 노래는 언제, 어떤 방식으로 현재 자리에 놓였는가","paragraphs":["2:1–10은 한나 개인의 출산 경험을 넘어 전쟁·세계 심판·왕권을 노래하기 때문에, 연구자들 사이에서는 이 시가 별도의 전승으로 존재하다가 현재의 출생 서사에 결합되었을 가능성을 논의합니다. 다른 해석은 현재 이야기 속의 한나가 자신의 경험을 이스라엘 전체의 미래를 비추는 언어로 확장하는 문학적 효과를 강조합니다. 노래의 형성 과정을 단일한 역사적 사건으로 복원할 결정적 증거는 여기서 확보되지 않습니다. 그러나 최종 본문이 1:28의 봉헌과 2:11의 사무엘 성소 생활 사이에 노래를 배치했다는 사실은 분명합니다. Benjamin Scolnic은 이 문제를 다루면서도, 현재 본문이 한나의 목소리로 노래를 들려준다는 사실의 의미를 강조합니다. John Goldingay는 사무엘의 출생·실로·엘리 집안과 왕의 준비를 하나의 큰 신학적 흐름 안에서 살핍니다. 여기서는 두 연구의 공개된 소개·초록 범위만 참고하였습니다."]},{"title":"'행동을 달아 보신다'는 말과 히브리어 독법","paragraphs":["2:3 끝에는 히브리어 자음 표기와 전통적으로 읽는 방식 사이에 차이가 보존되어 있습니다. OSHB v2.2는 이 차이를 드러내는 형태를 함께 기록합니다. 자음 표기(케티브)는 '그리고 …아니다'(וְלֹא)로 읽히고, 전통적 독법(케레)은 '그리고 그에 의해'(וְלוֹ)로 읽힙니다. '달아 보다'(נִתְכְּנוּ)는 수동형이므로, 케레를 따르면 '그분에 의해 행동이 달아 보아진다'가 되고 케티브를 따르면 '행동이 달아 보아지지 않는다'가 됩니다. 이 해설은 전통적 독법을 따라 읽습니다. 따라서 이 구절의 세부 구문을 마치 아무 논쟁도 없는 것처럼 설명하기보다는, 앞뒤 문맥에서 확실한 의미를 우선 읽는 편이 낫습니다. 교만한 말을 제지하는 명령과 '지식의 하나님'이라는 이유가 이어지므로, 하나님이 사람의 행동을 알고 평가하신다는 흐름은 뚜렷합니다. 번역 하나의 미세한 차이를 과장하여 노래 전체의 의미를 뒤집을 근거는 없습니다."]},{"title":"'일곱'과 실제 자녀 수","paragraphs":["2:5의 일곱은 시적 충만을 그리는 숫자입니다. 2:21은 한나가 뒤에 세 아들과 두 딸을 더 낳았다고 말합니다. 사무엘을 포함해도 여섯이므로, 2:5를 사후의 정확한 출생 기록으로 읽으면 두 본문이 서로 어긋납니다. 노래는 자녀 수를 세는 보고서가 아니라, 이전의 결핍이 뒤집힌 세계를 묘사합니다. 이 시적 성격을 존중해야 한나의 말이 지닌 힘이 더 정확히 살아납니다."]},{"title":"스올과 생명의 권능","paragraphs":["2:6의 '스올'을 개역한글은 '음부'로 옮깁니다. 이 말은 고대 이스라엘의 죽음 이해에 속한 언어입니다. '내려가게도 하시고 올라오게도 하신다'는 병행은 생사에 대한 하나님의 권한을 극적으로 표현합니다. 후대의 부활 소망과 신학적으로 연결해 읽을 수는 있지만, 이 절이 그 교리의 세부를 이미 직접 설명한다고 단정하지 않습니다. 먼저 노래가 말하는 범위에서 하나님의 권능을 듣고, 정경 전체의 발전은 별도로 구분해야 합니다."]},{"title":"거룩한 자들의 발과 '기름부음 받은 자'","paragraphs":["2:9에서 하나님이 지키시는 대상은 전통적 독법에서 복수인 '그에게 속한 신실한 사람들'로 나타나지만, 히브리어 기록에는 단수 형태와 관련된 전승상의 차이가 있습니다. 자음 표기(케티브)는 단수 '그의 신실한 자'(חֲסִידוֹ)이고 전통적 독법(케레)은 복수 '그의 신실한 자들'(חֲסִידָיו)입니다. 뒤따르는 동사 '지키신다'(יִשְׁמֹר)는 하나님을 주어로 하는 3인칭 단수이므로, 이 해설은 복수 독법에 따라 신실한 사람들 전체를 가리키는 것으로 읽습니다. 이 차이가 신실한 자를 돌보시는 하나님이라는 문맥의 중심을 바꾸지는 않습니다. 2:10의 '메쉬아흐'는 기름부음 받은 자라는 기본 의미를 지니며, 바로 앞의 '왕'과 연결됩니다. 2:10에도 같은 종류의 차이가 두 곳 있습니다. '그의 대적'은 자음 표기로는 단수(מריבו)이고 전통적 독법으로는 복수 '그의 대적들'(מריביו)이며, '그에게 맞서'도 자음 표기 עלו를 עליו로 읽습니다. 어느 쪽이든 여호와를 대적하는 자들이 부서지고 하늘에서 우레가 울린다는 흐름은 같습니다. 본문의 '메쉬아흐'는 '그의 기름부음 받은 자'(מְשִׁיחוֹ)로 소유 접미형이 붙어 있어, 앞의 '그의 왕'과 짝을 이룹니다. 사무엘서의 직접 문맥에서는 왕권을 가리키고, 후대 정경에서는 다윗 언약과 메시아 기대를 따라 더 넓은 의미로 읽힙니다. 그리스도교의 정경적 읽기에서 예수 그리스도와 연결되는 것은 이러한 후대의 신학적 종합이지, 2:10이 처음부터 예수의 생애를 상세히 기술한다는 뜻은 아닙니다."]},{"title":"시편과 마리아 찬가의 연결","paragraphs":["시편 113:7–9는 가난한 자를 먼지에서 일으키고 아이를 낳지 못하던 여인에게 기쁨을 주시는 하나님을 찬양합니다. 이는 한나의 노래와 표현·주제가 가까운 강한 평행입니다. 누가복음 1:46–55의 마리아 찬가 역시 낮은 자를 높이고 권세 있는 자를 낮추시는 하나님을 노래합니다. 이 연결은 단순히 '두 여인이 노래했다'는 유사성보다 깊습니다. 자신의 삶에서 경험한 하나님의 돌보심을 세상의 질서를 새롭게 평가하는 찬양으로 확장한다는 공통된 문학적 움직임이 있습니다. 그렇다고 두 노래의 모든 행을 일대일 예언과 성취로 맞추는 것은 본문이 허용하는 연결의 강도를 넘어섭니다."]}],"relatedResearch":[],"readerSources":[],"notes":["연구 참고자료","* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:21–2:11 및 관련 본문 · 권리자 대한성서공회, 공개 재배포 허락 별도 확인 필요.\n   * 본문 확인: https://www.bible.com/ko/bible/88/1SA.2.KRV\n   * 이 주석은 해당 번역의 장문을 복제하지 않고 독립 한국어 해설로 재서술하였습니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.2.1–10 · 표제어·형태 주석 CC BY 4.0, 기반 Westminster Leningrad Codex 히브리어 본문 Public Domain.\n   * 공식 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n   * 프로젝트·권리: https://github.com/openscriptures/morphhb\n   * 히브리어 형태와 독법을 확인하고 한국어 설명을 새로 작성하였습니다. 원어 원본을 수정하지 않았습니다.\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · `WORBS_사무엘상1장_필터최소패치_v0.2.md`, 사무엘상 1:1–2:10 문학적 확장 범위 · 기존 연구의 본문·문학·신학적 관찰을 확인하고 해당 노래 부분을 새 산문으로 재구성하였습니다. 외부 이용·재배포 권리는 별도 확인 대상입니다.\n* 『1SA_1Samuel_BOOK_PROFILE_Theological_Filter』 · Jude Lee OS · v0.2, 사무엘상 책 전체의 왕정·말씀·신학적 문맥 · 본문 해석을 보조하는 연구 자료이며 외부 재배포 권리는 별도 확인 대상입니다.\n* “I Am the Woman: The Story and Prayer of Hannah, a Biblical Feminist Text” · Benjamin Scolnic · Jewish Bible Quarterly 51:1 (2023), 23–32 · 공개 초록 및 소개만 확인, 저작권자·재이용 허락은 별도 확인 대상.\n   * 공식 원문 안내: https://www.jewishbible.org/articles/i-am-the-woman-story-and-prayer-of-hannah/\n* The Theology of the Book of Samuel, Chapter 2 “Yahweh Who Prepares the Way for a King (1 Samuel 1:1–4:1a)” · John Goldingay · Cambridge University Press, 2024, pp. 14–49 · 출판사 공개 장 소개·요약만 확인, 저작권자 Cambridge University Press.\n   * 공식 장 소개: https://www.cambridge.org/core/books/abs/theology-of-the-book-of-samuel/yahweh-who-prepares-the-way-for-a-king-1-samuel-1141a/AD48E74D2FE447267A92B62BCB536F5A","연구 및 재서술 안내","이 글은 사무엘상 2:1–10의 히브리어 본문과 확인된 한국어 성경, 기존 WORBS 연구 및 위에 밝힌 자료의 실제 확인 범위를 토대로 한국어 산문을 새롭게 구성한 주석입니다. 원어 설명·본문 구조·정경 연결을 독자가 따라갈 수 있도록 풀어썼으며, 학술 자료의 전문을 열람하거나 인용하지 않은 경우에는 공개된 소개·초록을 참고한 범위를 넘어서 주장하지 않았습니다. 기존 연구와의 저작권상 독립·파생 관계는 별도 검토가 필요합니다.","라이선스","OSHB의 표제어·형태 분석 자료에는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이 적용되고, 그 기반 Westminster Leningrad Codex 히브리어 본문은 Public Domain입니다. 개역한글판과 개별 학술자료·기존 연구의 권리는 각각의 권리자에게 남아 있으며, 이 주석 전체에 단일한 공개 라이선스가 확정된 것은 아닙니다."],"sourceNotice":"연구 참고자료\n\n* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:21–2:11 및 관련 본문 · 권리자 대한성서공회, 공개 재배포 허락 별도 확인 필요.\n   * 본문 확인: https://www.bible.com/ko/bible/88/1SA.2.KRV\n   * 이 주석은 해당 번역의 장문을 복제하지 않고 독립 한국어 해설로 재서술하였습니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.2.1–10 · 표제어·형태 주석 CC BY 4.0, 기반 Westminster Leningrad Codex 히브리어 본문 Public Domain.\n   * 공식 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n   * 프로젝트·권리: https://github.com/openscriptures/morphhb\n   * 히브리어 형태와 독법을 확인하고 한국어 설명을 새로 작성하였습니다. 원어 원본을 수정하지 않았습니다.\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · `WORBS_사무엘상1장_필터최소패치_v0.2.md`, 사무엘상 1:1–2:10 문학적 확장 범위 · 기존 연구의 본문·문학·신학적 관찰을 확인하고 해당 노래 부분을 새 산문으로 재구성하였습니다. 외부 이용·재배포 권리는 별도 확인 대상입니다.\n* 『1SA_1Samuel_BOOK_PROFILE_Theological_Filter』 · Jude Lee OS · v0.2, 사무엘상 책 전체의 왕정·말씀·신학적 문맥 · 본문 해석을 보조하는 연구 자료이며 외부 재배포 권리는 별도 확인 대상입니다.\n* “I Am the Woman: The Story and Prayer of Hannah, a Biblical Feminist Text” · Benjamin Scolnic · Jewish Bible Quarterly 51:1 (2023), 23–32 · 공개 초록 및 소개만 확인, 저작권자·재이용 허락은 별도 확인 대상.\n   * 공식 원문 안내: https://www.jewishbible.org/articles/i-am-the-woman-story-and-prayer-of-hannah/\n* The Theology of the Book of Samuel, Chapter 2 “Yahweh Who Prepares the Way for a King (1 Samuel 1:1–4:1a)” · John Goldingay · Cambridge University Press, 2024, pp. 14–49 · 출판사 공개 장 소개·요약만 확인, 저작권자 Cambridge University Press.\n   * 공식 장 소개: https://www.cambridge.org/core/books/abs/theology-of-the-book-of-samuel/yahweh-who-prepares-the-way-for-a-king-1-samuel-1141a/AD48E74D2FE447267A92B62BCB536F5A\n\n연구 및 재서술 안내\n\n이 글은 사무엘상 2:1–10의 히브리어 본문과 확인된 한국어 성경, 기존 WORBS 연구 및 위에 밝힌 자료의 실제 확인 범위를 토대로 한국어 산문을 새롭게 구성한 주석입니다. 원어 설명·본문 구조·정경 연결을 독자가 따라갈 수 있도록 풀어썼으며, 학술 자료의 전문을 열람하거나 인용하지 않은 경우에는 공개된 소개·초록을 참고한 범위를 넘어서 주장하지 않았습니다. 기존 연구와의 저작권상 독립·파생 관계는 별도 검토가 필요합니다.\n\n라이선스\n\nOSHB의 표제어·형태 분석 자료에는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이 적용되고, 그 기반 Westminster Leningrad Codex 히브리어 본문은 Public Domain입니다. 개역한글판과 개별 학술자료·기존 연구의 권리는 각각의 권리자에게 남아 있으며, 이 주석 전체에 단일한 공개 라이선스가 확정된 것은 아닙니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_02_11_17_WORBS_READER_DRAFT_20261021","researchType":"WORBS","researchDepth":"CORE","sourcePath":"C:/Users/언약의~1/AppData/Local/Temp/claude/C--Users--------codex-worktrees-judebible-runtime-integration---/9427b599-5413-43f5-8bb9-3682554439fe/scratchpad/1sa2-copies/1SA_02_11_17_WORBS_READER_DRAFT_20261021.md","sourceSha256":"2dbafcc3409370930eb562b631cf03f50e834d8c3fd9356e3ed5ff7a2d51e35e","passage":{"book":"1sa","chapter":2,"v1":11,"v2":17,"ref":"사무엘상 2:11–17"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"제사의 자리를 빼앗은 사람들","overview":["한나는 사무엘을 여호와께 드린 뒤, 낮은 자를 높이시고 사람의 행동을 살피시는 하나님을 노래하였다(1:21–2:10). 노래가 끝나자 엘가나는 집으로 돌아가고 어린 사무엘은 실로에 남습니다. 이야기는 같은 성소 안에 있는 서로 다른 사람들을 보여 줍니다. 한쪽에는 여호와를 섬기는 아이가 있고, 다른 쪽에는 제사장 집안에 속해 있으면서도 여호와를 알지 못한다고 평가받는 사람들이 있습니다.","본문은 성소의 부패를 추상적으로 비난하지 않습니다. 제사장의 사환이 고기를 어떻게 가져가는지, 예배자가 어떤 순서를 지키자고 말하는지, 그 말에 어떤 위협이 돌아오는지 차례로 보여 줍니다. **이 단락의 중심은 거룩한 직분을 맡았다는 사실이 하나님을 존중한다는 증거가 아니라는 데 있습니다. 제사의 질서를 자기 몫을 얻는 수단으로 바꾼 행위는 결국 여호와께 드리는 예물 자체를 멸시하는 일이 됩니다.**"],"centralMessage":"사무엘의 섬김과 엘리 아들들의 행위는 아직 직접 충돌하지 않습니다. 그러나 저자는 둘을 가까이 놓음으로써 독자가 그 차이를 보게 합니다. 뒤이어 사무엘의 성장(2:18–21, 26)과 엘리 집안에 대한 책망(2:22–36)이 교차할 때 이 첫 장면의 의미는 더욱 분명해집니다.","literaryStructure":[{"v1":11,"v2":11,"title":"집으로 돌아간 아버지와 성소에 남은 아이"},{"v1":12,"v2":12,"title":"제사장의 아들들이 여호와를 알지 못한다"},{"v1":13,"v2":14,"title":"갈고리가 정한 몫, 반복되는 제물 취득"},{"v1":15,"v2":16,"title":"하나님께 드리기 전에 먼저 내놓으라는 요구"},{"v1":17,"v2":17,"title":"사람의 몫을 탐한 죄가 하나님의 제사를 멸시하는 죄가 되다"}],"sections":[{"id":"1sa2-11-11","v1":11,"v2":11,"title":"집으로 돌아간 아버지와 성소에 남은 아이","paragraphs":["한나의 노래 다음에는 짧은 이동 장면이 나옵니다. 엘가나는 라마의 자기 집으로 돌아가고, 아이 사무엘은 제사장 엘리 앞에서 여호와를 섬깁니다. 이 장면은 사무엘이 이미 어른이 되었다는 뜻이 아닙니다. 앞선 1:21–28에서 부모가 서원을 이행하여 아이를 성소에 맡겼고, 이제 그 결정이 지속적인 섬김으로 이어진다는 뜻입니다. 본문은 그날 사무엘이 구체적으로 어떤 일을 맡았는지, 부모와 떨어져 어떤 마음이었는지 설명하지 않습니다. 기록된 것은 그가 머문 자리와 그곳에서 섬기는 대상입니다.","히브리어 ‘메샤레트’(מְשָׁרֵת)는 곁에서 시중들거나 맡은 일을 수행하는 섬김을 가리킵니다. 사무엘은 엘리의 지도 아래 있지만, 서술은 그의 섬김을 여호와께 향한 것으로 표현합니다. 사람을 통해 배우는 모습과 그 봉사의 궁극적인 방향이 한 문장에 담겨 있습니다. 이것을 훗날 사무엘의 선지자적 사역이 이미 완성되었다는 뜻으로 읽을 수는 없습니다. 사무엘상 3장은 그가 여호와의 말씀을 듣게 되는 과정을 따로 보여 줍니다.","이 절은 앞선 한나의 봉헌과 뒤따르는 제사장들의 행동을 연결하는 문턱입니다. 한나는 받은 아들을 여호와께 돌려드렸고, 사무엘은 성소에 남아 섬깁니다. 곧 등장하는 엘리의 아들들은 이미 제사장 집안에 속해 있으면서도 여호와께 드려진 것을 자기 몫으로 다룹니다. 한쪽은 드림에서 시작하고 다른 쪽은 가져감에서 드러나는 대조입니다. 다만 저자는 사무엘을 처음부터 모든 것을 아는 완전한 인물로 묘사하지 않고 성장하는 아이로 그립니다."]},{"id":"1sa2-12-12","v1":12,"v2":12,"title":"제사장의 아들들이 여호와를 알지 못한다","paragraphs":["서술자는 엘리의 아들들을 소개하면서 곧바로 판단을 내립니다. 그들은 ‘불량자’이며 여호와를 알지 못한다고 합니다. 홉니와 비느하스라는 이름은 이미 1:3에서 실로의 제사장들로 언급되었습니다. 그러므로 이들은 성소 밖에서 침입한 낯선 사람들이 아니라, 성소의 제사에 관여할 수 있는 위치에 있는 사람들입니다. 바로 그 지위와 저자의 평가 사이에 긴장이 생깁니다.","‘불량자’에 해당하는 히브리어 ‘브네 벨리야알’(בְּנֵי בְלִיָּעַל)은 가치 없음과 사악함을 나타내는 관용적인 표현입니다. 이 말은 별도의 인물에 관한 족보를 제시하는 것이 아니며, 후대의 특정 악한 존재에 관한 교리적 명칭으로 먼저 바꾸어 읽을 필요도 없습니다. 이어지는 13–17절이 그 평가를 행동으로 풀어 줍니다.","‘여호와를 알지 못한다’는 말도 종교 정보를 전혀 배우지 못했다는 뜻으로만 이해하기 어렵습니다. 이들은 제사장의 집안에서 제물을 다루는 위치에 있었습니다. 그럼에도 여호와를 ‘모른다’고 말하는 까닭은 그들의 행동이 하나님께 속한 것을 하나님께 속한 것으로 인정하지 않기 때문입니다. 이 문맥에서 하나님을 아는 것은 단순한 지식과 직함이 아니라 그분의 뜻을 존중하는 관계와 연결됩니다.","한나의 노래는 여호와가 사람의 행동을 달아 보시는 하나님이라고 선언하였다(2:3). 바로 뒤에 나오는 이 평가는 그 노래의 원리가 성소 내부에도 적용된다는 사실을 보여 줍니다. 하나님의 판단은 성소 밖의 교만한 사람에게만 향하지 않습니다. 여호와의 이름으로 직무를 수행하는 사람도 그분 앞에서 평가받습니다."]},{"id":"1sa2-13-14","v1":13,"v2":14,"title":"갈고리가 정한 몫, 반복되는 제물 취득","paragraphs":["이제 저자는 구체적인 절차를 설명합니다. 누군가 제사를 드리고 고기를 삶을 때, 제사장의 사환이 세 갈래로 된 갈고리를 들고 옵니다. 그는 그것을 솥이나 가마에 찔러 넣고 걸려 나오는 것을 제사장의 몫으로 가져갑니다. 여러 종류의 그릇이 차례로 언급되고, 실로에 온 이스라엘 사람들에게 이런 일이 행해졌다고 덧붙입니다. 단 한 번의 우발적인 다툼이 아니라 반복된 관행이라는 인상을 주는 서술입니다.","13절의 ‘미슈파트’(מִשְׁפָּט)는 문맥에 따라 규정된 몫이나 권리, 관행을 나타낼 수 있습니다. 따라서 ‘제사장들이 백성에게 행하는 습관’이라는 번역만으로 그 행위가 합법적인 규정이었다고 판단할 수는 없습니다. 저자는 제사장 측이 실제로 어떻게 행동했는지를 먼저 보여 주고, 마지막 17절에서 그 행위에 대한 판단을 내립니다. 어떤 관행이 오래 반복되었다는 사실과 그것이 정당하다는 판단은 서로 다릅니다.","이스라엘의 제사 규정에는 제사장이 제물의 일정한 몫을 받도록 정한 조항이 있습니다. 특히 레위기 7:30–34는 화목제에서 여호와께 드릴 기름을 불사르고, 정해진 부분을 제사장에게 돌리는 질서를 설명합니다. 그러므로 본문이 비판하는 것은 제사장이 고기를 먹는 일 자체가 아닙니다. 문제가 되는 것은 자신에게 허락된 몫과 절차를 존중하기보다 갈고리에 걸리는 것을 임의로 취하는 방식, 그리고 다음 장면에서 더욱 분명하게 드러나는 강압입니다.","저자는 갈고리의 정확한 길이나 성소 부엌의 구조를 알려 주지 않습니다. 그 세부를 복원하지 않아도 장면의 핵심은 충분히 보입니다. 제사를 드리러 온 사람은 하나님께 예물을 바치고 있는데, 제사장의 사환은 그 예물이 자기 주인에게 얼마나 돌아갈 것인가를 먼저 생각하게 만듭니다. 예배자가 드리는 행위의 중심에 있어야 할 여호와가 주변으로 밀려나고, 제사장 측의 취득 행위가 장면을 지배합니다."]},{"id":"1sa2-15-16","v1":15,"v2":16,"title":"하나님께 드리기 전에 먼저 내놓으라는 요구","paragraphs":["15절은 앞의 관행보다 더 심각한 일을 덧붙입니다. 기름을 제단에서 태우기도 전에 사환이 와서 제사장에게 구워 줄 날고기를 내놓으라고 요구합니다. 삶은 고기는 받지 않겠다는 말도 전합니다. 여기에는 단순히 조리법을 선호한다는 정보 이상의 문제가 있습니다. 제사에서 먼저 여호와께 드려야 할 부분을 드리는 순서가 아직 끝나지 않았는데, 제사장 측이 자기 몫을 먼저 확보하려 합니다.","레위기 3장과 7장에서 기름을 제단에 불사르는 일은 제사에서 여호와께 속한 몫을 드리는 중요한 행위입니다. 이 규정을 연결할 때 당시 실로의 모든 제사가 동일한 세부 방식으로 진행되었다고 단정할 필요는 없습니다. 그러나 이 이야기 자체가 ‘기름을 태우기 전’이라는 시간을 강조하고, 제사를 드리는 사람도 그 순서를 문제 삼는다는 사실은 분명합니다. 갈등의 핵심은 맛이나 취향이 아니라, 누가 먼저 존중받아야 하는가 하는 질서에 있습니다.","16절에서 제사를 드리는 사람은 기름을 먼저 태운 다음 원하는 대로 가져가라고 제안합니다. 이 사람은 제사장에게 아무것도 주지 않겠다고 거부하지 않습니다. 하나님께 드릴 몫을 먼저 드리자는 것입니다. 그런데 사환은 지금 당장 내놓으라고 대답하고, 그렇지 않으면 힘으로 빼앗겠다고 위협합니다. 본문은 피해자의 속마음이나 실제 몸싸움의 경과를 묘사하지 않습니다. 기록된 발화만으로도 권력을 가진 쪽이 예배자의 정당한 요청을 묵살하고 있음을 알 수 있습니다.","‘억지로’에 해당하는 ‘베하즈카’(בְּחָזְקָה)는 힘이나 강제력을 동원하는 방식을 가리킵니다. 이것은 앞 절의 관행이 단순한 절차상의 실수만은 아니었음을 보여 줍니다. 제사장의 이름으로 움직이는 사환이 예배자에게 압박을 가하고, 하나님의 몫을 먼저 드리려는 요구를 제압하려 합니다. 성소에서 주어진 직무가 사람을 돕는 통로가 아니라 사람을 누르는 힘으로 변질된 것입니다.","이 대화가 특별히 아픈 까닭은 예배자가 제사의 질서를 지키려 하고, 그것을 집행해야 할 쪽이 그 질서를 무너뜨리고 있기 때문입니다. 제사장의 직무는 하나님께 드리는 예물이 올바르게 다루어지도록 돕는 일이지만, 이 장면에서는 오히려 제사를 드리는 사람이 그 기본 순서를 지키자고 호소합니다. 저자는 누가 하나님께 속한 것을 더 진지하게 대하는지를 직함이 아니라 행동과 말로 보여 줍니다."]},{"id":"1sa2-17-17","v1":17,"v2":17,"title":"사람의 몫을 탐한 죄가 하나님의 제사를 멸시하는 죄가 되다","paragraphs":["마지막 절은 앞서 들려준 행동을 한 문장으로 평가합니다. 그 젊은이들의 죄가 여호와 앞에 매우 컸다는 것입니다. 갈고리로 고기를 가져가는 관행과 강압적인 요구를 설명한 뒤에 비로소 ‘죄’라는 평가가 나옵니다. 독자는 판단의 이유를 이미 보았습니다. 문제는 제사장이 허락된 것보다 더 많은 고기를 얻었다는 데 그치지 않습니다. 하나님께 드리는 예물을 자신의 요구에 종속시켜 버렸다는 데 있습니다.","17절의 ‘멸시하다’에 해당하는 동사 ‘니아추’(נִאֲצוּ)는 가볍게 여기고 업신여기는 태도를 나타냅니다. ‘민하’(מִנְחָה)는 여기서 좁은 의미의 곡식 제사만을 가리키기보다 여호와께 드리는 예물이라는 넓은 뜻으로 쓰인 것으로 읽는 것이 자연스럽습니다. 제사장들의 잘못을 제물 관리상의 사소한 실수로 축소할 수 없는 이유입니다. 예물은 그것을 바치는 사람이 하나님께 향하여 드리는 것이며, 그 예물을 멸시하는 일은 그 관계를 훼손합니다.","히브리어 문장은 누가 예물을 멸시했는지를 번역할 때 세심한 주의를 요구합니다. 마소라 본문에는 ‘그 사람들’이라는 명사가 따로 있어, 직접적으로 엘리의 아들들 또는 그들의 사환을 가리키는지, 더 넓게 예배자들까지 제사를 싫어하게 되었다는 뜻인지 논의가 있습니다. 일부 고대 본문 전승에서는 이 명사가 나타나지 않습니다. 그러므로 ‘모든 백성이 이미 제사를 거부했다’거나 ‘사환만 죄를 지었고 제사장들은 책임이 없다’고 단정하기 어렵습니다. 다만 앞의 행동과 17절의 판단이 연결되어 있으며, 여호와의 예물이 심각하게 경멸당했다는 중심 의미는 분명합니다.","이 판단은 한나의 노래와 다음 이야기의 연결점이 됩니다. 한나는 하나님이 교만한 말을 막으시고 행동을 살피신다고 노래하였다(2:3). 이제 그 판단이 제사장의 집안에 내려집니다. 반면 바로 다음 18절에서는 어린 사무엘이 여호와 앞에서 섬기고 있습니다. 성소의 부패가 하나님을 섬기는 일 자체를 사라지게 하지는 않습니다. 같은 자리에서 서로 다른 방향의 삶이 자라고 있으며, 이어지는 이야기는 그 차이가 어떻게 드러나는지 보여 줍니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘알지 못한다’는 말은 무엇을 뜻하는가","paragraphs":["12절의 ‘여호와를 알지 못한다’는 판단을 종교 교육을 받지 못했다는 설명으로 읽으면 이야기의 날카로움이 약해집니다. 이들은 제사장의 집안에서 예물에 접근할 수 있는 사람들이었습니다. 문제는 절차를 전혀 몰랐다는 사실이 아니라, 하나님의 몫을 존중하는 방식으로 행동하지 않았다는 데 있습니다. 뒤의 2:29는 엘리 집안이 제물과 예물을 짓밟고 아들들을 하나님보다 중히 여겼다는 책망을 전합니다. 12–17절의 행동은 그 책망이 왜 주어지는지 보여 주는 앞선 근거입니다. 다만 엘리 개인의 모든 책임을 이 짧은 단락만으로 완결해 판단하지 않고, 2:22–36의 후속 서술과 함께 읽어야 합니다."]},{"title":"‘제사장의 미슈파트’와 합당한 몫의 구별","paragraphs":["13절의 ‘미슈파트’는 법적 권리와 실제 관행을 모두 가리킬 수 있는 말입니다. 여기서 사환의 갈고리가 정하는 몫을 율법이 승인한 권리와 동일시해서는 안 됩니다. 레위기 7:30–34의 제사장 몫은 여호와께 드리는 부분과 구별된 절차 안에 놓여 있습니다. 사무엘상은 어떤 종류의 제물이 모든 장면에 해당했는지까지 목록으로 제시하지 않습니다. 그러나 15–16절에서 예배자가 ‘기름을 먼저 태우자’고 요청한다는 점은 그 질서가 무너지고 있음을 분명하게 합니다. 제사의 목적과 순서를 읽어야 탐욕이 왜 신학적 죄로 규정되는지 이해할 수 있습니다."]},{"title":"17절의 주어와 본문 전승","paragraphs":["마소라 본문은 ‘젊은이들’과 ‘그 사람들’이라는 두 표현을 사용합니다. 문맥상 두 표현이 엘리의 아들들 또는 사환을 가리키는 방식에는 여러 가능성이 있습니다. 그 결과 예배자들까지 제사에 염증을 느끼게 되었다는 해석도 제시됩니다. 한편 칠십인역과 쿰란의 한 사본에서는 ‘그 사람들’에 해당하는 명사가 나타나지 않는다는 점이 번역 논의에서 중요합니다. Roger L. Omanson과 John E. Ellington의 번역자 안내서는 이러한 차이를 소개하면서, 제물을 멸시한 주체를 그 젊은이들로 이해하는 번역을 검토합니다. 어느 독법을 택하든 저자의 핵심 판정은 달라지지 않습니다. 제사를 맡은 이들의 행위가 여호와께 드리는 예물을 업신여기는 결과를 낳았다는 것입니다."]},{"title":"16절의 케티브와 케레","paragraphs":["16절에서 사환의 대답을 이끄는 낱말은 자음 표기(케티브)로는 '그에게'(לוֹ)이고 전통적 독법(케레)으로는 '아니다'(לֹא)입니다. 케레를 따르면 사환은 '아니다, 지금 내놓아라'라고 거절하며 요구하는 말을 하고, 케티브를 따르면 '그에게 말하기를, 지금 내놓아야 한다'는 문장이 됩니다. 어느 쪽이든 사환이 기름을 먼저 태우자는 요청을 받아들이지 않고 지금 고기를 내라고 요구하며, 그렇지 않으면 힘으로 가져가겠다고 말하는 장면의 요지는 달라지지 않습니다."]},{"title":"한나의 노래와 엘리 집안의 대조는 어떤 연결인가","paragraphs":["2:3의 ‘행동을 달아 보시는 하나님’과 2:17의 ‘여호와 앞에 매우 큰 죄’는 서로 이어 읽을 만한 문학적·신학적 연결입니다. 이것은 한나가 엘리 아들들의 세부 행동을 미리 알고 노래했다는 역사적 주장과 다릅니다. 책의 현재 배열 속에서 노래가 뒤따르는 인물들을 평가하는 관점을 제공한다는 뜻입니다. 사무엘의 섬김(2:11, 18)과 엘리 아들들의 죄(2:12–17, 22–25)를 번갈아 보여 주는 구성도 같은 효과를 냅니다. 훗날 사무엘이 말씀을 듣고 전하는 장면(3장)으로 이어지는 흐름을 보면, 성소의 직분을 가진 사람과 여호와의 말씀에 응답하는 사람을 구별하는 것이 사무엘서의 중요한 관심사임을 알 수 있습니다."]},{"title":"이 단락에서 역사적으로 확인할 수 있는 범위","paragraphs":["이야기의 장소는 실로이며, 성소에서 제사장과 사환, 제사를 드리는 사람이 관여하는 제물 처리의 모습을 서술합니다. 그러나 이 일의 정확한 연대, 갈고리의 실제 크기, 그릇의 배치, 당시 실로 성소의 전체 구조는 본문만으로 재구성할 수 없습니다. 구체적인 도구와 음식 처리 장면은 고대 예배가 몸과 물질을 동반한 실제 행위였음을 드러내지만, 그 사실을 넘어 확인되지 않은 고고학적 세부를 덧붙일 필요는 없습니다. 본문이 독자에게 요구하는 주의는 상상 속 성소를 복원하는 데보다, 그곳에서 누가 무엇을 먼저 차지하려 했는지를 보는 데 있습니다."]}],"relatedResearch":[],"readerSources":[],"notes":["연구 참고자료","* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 2:11–17 및 1:21–2:36, 레위기 3장·7:30–34 등 관련 본문 · 저작권자 대한성서공회. 공개 재배포 허락은 별도 확인이 필요합니다.\n   * 확인한 본문: https://www.bible.com/ko/bible/88/1SA.2.KRV\n   * 관련 제사 규정: https://www.bible.com/bible/88/LEV.7.14%2C30-34.KRV\n   * 본문 장문을 전재하지 않고 내용을 한국어 산문으로 새로 설명하였습니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.2.11–17 · 형태·분석 데이터 CC BY 4.0, 기반 Westminster Leningrad Codex 히브리어 본문 Public Domain.\n   * 공식 본문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n   * 프로젝트와 권리: https://github.com/openscriptures/morphhb\n   * 히브리어 어형과 구문을 확인하고 한국어 풀이를 새로 작성하였습니다. 원본 데이터는 수정하지 않았습니다.\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · WORBS_사무엘상1장_필터최소패치_v0.2.md, 사무엘상 1:1–2:10의 직접 앞 문맥 · 기존 연구의 사무엘 출생·한나의 노래·엘리 집안 대조를 문맥 자료로 확인하고 본 단락 해설은 새로 구성하였습니다. 외부 재사용 권리는 별도 확인 대상입니다.\n* BOOK PROFILE BUNDLE — OT02 HISTORICAL BOOKS · Jude Lee OS · v1.0_APPROVED, BP-OT02-1SA 사무엘상 문맥 · 사무엘서의 문학·왕정·말씀 주제를 이해하는 내부 참고자료. 외부 재사용 권리는 별도 확인 대상입니다.\n* A Handbook on the First and Second Books of Samuel, Volume 1 · Roger L. Omanson, John E. Ellington · UBS Helps for Translators, United Bible Societies, New York, 2001, 사무엘상 2:17 번역 주석의 공개 인용 부분 · 저작권자 United Bible Societies.\n   * 공개된 번역 주석: https://tips.translation.bible/tip_verse/1sam-217/\n   * 17절의 주어와 고대 본문 차이에 관한 공개된 설명만 참고하여 한국어로 재서술하였고 원문을 장문 전재하지 않았습니다.","연구 및 재서술 안내","이 주석은 사무엘상 2:11–17의 한국어 성경과 히브리어 본문을 읽고, 앞 단락에 대한 기존 WORBS 연구와 확인된 번역 연구를 참고하여 장면별로 새롭게 구성한 한국어 해설입니다. 성소에서 벌어진 행동과 발화를 본문 순서에 따라 설명하되, 본문이 알려 주지 않는 인물의 심리나 구체적인 역사 상황을 덧붙이지 않았습니다. 기존 연구와의 저작권상 독립·파생 관계는 별도 확인이 필요합니다.","라이선스","OSHB의 형태·분석 데이터에는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이 적용되며 기반 Westminster Leningrad Codex 히브리어 본문은 Public Domain입니다. 개역한글판, 내부 WORBS 연구, Book Profile 및 UBS 번역 연구의 권리는 각 권리자에게 남아 있습니다. 이 주석 전체에 적용할 공개 라이선스는 별도로 확정되지 않았습니다."],"sourceNotice":"연구 참고자료\n\n* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 2:11–17 및 1:21–2:36, 레위기 3장·7:30–34 등 관련 본문 · 저작권자 대한성서공회. 공개 재배포 허락은 별도 확인이 필요합니다.\n   * 확인한 본문: https://www.bible.com/ko/bible/88/1SA.2.KRV\n   * 관련 제사 규정: https://www.bible.com/bible/88/LEV.7.14%2C30-34.KRV\n   * 본문 장문을 전재하지 않고 내용을 한국어 산문으로 새로 설명하였습니다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.2.11–17 · 형태·분석 데이터 CC BY 4.0, 기반 Westminster Leningrad Codex 히브리어 본문 Public Domain.\n   * 공식 본문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n   * 프로젝트와 권리: https://github.com/openscriptures/morphhb\n   * 히브리어 어형과 구문을 확인하고 한국어 풀이를 새로 작성하였습니다. 원본 데이터는 수정하지 않았습니다.\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · WORBS_사무엘상1장_필터최소패치_v0.2.md, 사무엘상 1:1–2:10의 직접 앞 문맥 · 기존 연구의 사무엘 출생·한나의 노래·엘리 집안 대조를 문맥 자료로 확인하고 본 단락 해설은 새로 구성하였습니다. 외부 재사용 권리는 별도 확인 대상입니다.\n* BOOK PROFILE BUNDLE — OT02 HISTORICAL BOOKS · Jude Lee OS · v1.0_APPROVED, BP-OT02-1SA 사무엘상 문맥 · 사무엘서의 문학·왕정·말씀 주제를 이해하는 내부 참고자료. 외부 재사용 권리는 별도 확인 대상입니다.\n* A Handbook on the First and Second Books of Samuel, Volume 1 · Roger L. Omanson, John E. Ellington · UBS Helps for Translators, United Bible Societies, New York, 2001, 사무엘상 2:17 번역 주석의 공개 인용 부분 · 저작권자 United Bible Societies.\n   * 공개된 번역 주석: https://tips.translation.bible/tip_verse/1sam-217/\n   * 17절의 주어와 고대 본문 차이에 관한 공개된 설명만 참고하여 한국어로 재서술하였고 원문을 장문 전재하지 않았습니다.\n\n연구 및 재서술 안내\n\n이 주석은 사무엘상 2:11–17의 한국어 성경과 히브리어 본문을 읽고, 앞 단락에 대한 기존 WORBS 연구와 확인된 번역 연구를 참고하여 장면별로 새롭게 구성한 한국어 해설입니다. 성소에서 벌어진 행동과 발화를 본문 순서에 따라 설명하되, 본문이 알려 주지 않는 인물의 심리나 구체적인 역사 상황을 덧붙이지 않았습니다. 기존 연구와의 저작권상 독립·파생 관계는 별도 확인이 필요합니다.\n\n라이선스\n\nOSHB의 형태·분석 데이터에는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이 적용되며 기반 Westminster Leningrad Codex 히브리어 본문은 Public Domain입니다. 개역한글판, 내부 WORBS 연구, Book Profile 및 UBS 번역 연구의 권리는 각 권리자에게 남아 있습니다. 이 주석 전체에 적용할 공개 라이선스는 별도로 확정되지 않았습니다."}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("1sa");})(window);
